-- Integrate inside one atomic15recipe lote04 transaction ONLY after all15ready,
-- CI/merge and observed deployed media hashes. Caller must set the batch gate.
DO $greek_salad$
DECLARE
 j constant jsonb := $records$[{"id": "fb8402a9-e0f5-4636-865a-1a7b3a92d5bf", "recipe_group_id": "031f1a9c-6240-4ab4-9027-568a18de7ffe", "slug": "receta-de-ensalada-griega", "public_path": "/receta-de-ensalada-griega", "source_url": "https://manualdecocina.com/receta-de-ensalada-griega/", "language": "es", "title": "Ensalada griega propuesta con feta y aceitunas", "excerpt": "Tomate, pepino, feta y aceitunas con aliño medido, sin lechuga y con frío incluido para cuatro raciones propuestas.", "summary": "Ensalada propuesta de inspiración griega con tomate, pepino, pimiento verde, cebolla, feta pasteurizado y aceitunas negras maduras. Se proponen 4 raciones y 50 minutos completos, incluidos 30 de frío, sin cocción y pendientes de confirmación en cocina.", "category": "Ensaladas", "category_slug": "ensaladas", "difficulty": "Fácil", "course": "Ensalada", "cuisine": "Inspiración griega", "prep_time_minutes": 20, "cook_time_minutes": 0, "total_time_minutes": 50, "servings": 4, "ingredients": [{"name": "tomate rojo maduro, sin pedúnculo", "amount": "500", "unit": "g", "group": "Ensalada"}, {"name": "pepino limpio con piel", "amount": "300", "unit": "g", "group": "Ensalada"}, {"name": "pimiento verde, sin tallo ni semillas", "amount": "120", "unit": "g", "group": "Ensalada"}, {"name": "cebolla roja pelada", "amount": "80", "unit": "g", "group": "Ensalada"}, {"name": "queso feta entero de leche pasteurizada, escurrido", "amount": "160", "unit": "g", "group": "Ensalada"}, {"name": "aceitunas negras maduras en conserva, sin hueso y escurridas, tamaño pequeño a extragrande", "amount": "80", "unit": "g", "group": "Ensalada"}, {"name": "aceite de oliva", "amount": "30", "unit": "g", "group": "Aliño"}, {"name": "vinagre de vino tinto", "amount": "20", "unit": "g", "group": "Aliño"}, {"name": "orégano seco", "amount": "1", "unit": "g", "group": "Aliño"}, {"name": "sal fina", "amount": "1", "unit": "g", "group": "Aliño"}], "steps": [{"title": "Lava y pesa", "content": "Lávate las manos y prepara báscula, tabla, cuchillo, cuenco grande y recipiente con tapa. Lava tomate, pepino y pimiento bajo agua corriente sin jabón y seca. Pesa 500 g de tomate sin pedúnculo, 300 g de pepino con piel, 120 g de pimiento sin tallo ni semillas y 80 g de cebolla pelada. Escurre y pesa 160 g de feta pasteurizado y 80 g de aceitunas negras comerciales ya maduras, sin hueso; no uses el líquido de conserva. Pesa aparte 30 g de aceite, 20 g de vinagre, 1 g de orégano y 1 g de sal. Dedica unos 5 minutos y sigue las etiquetas de queso y aceitunas; mantén el queso refrigerado hasta cortarlo.", "image_url": "/recetas/receta-de-ensalada-griega/paso-01.webp", "image_alt": "Ensalada griega propuesta: Lava y pesa"}, {"title": "Corta verduras y queso", "content": "Corta tomate en trozos de unos 2 cm, pepino con piel en medias lunas de unos 1 cm, pimiento en tiras y cebolla en láminas finas. Conserva las semillas comestibles y los jugos del tomate, sin escurrir las verduras. Corta el feta en dados con utensilios limpios, sin deshacerlo. Revisa que ninguna aceituna conserve hueso. Dedica unos 8 minutos y reúne verduras y aceitunas en el cuenco; reserva el feta en frío.", "image_url": "/recetas/receta-de-ensalada-griega/paso-02.webp", "image_alt": "Ensalada griega propuesta: Corta verduras y queso"}, {"title": "Prepara el aliño medido", "content": "Mezcla en un cuenco pequeño los 30 g de aceite, los 20 g de vinagre, el 1 g de orégano y el 1 g de sal hasta dispersarlos, durante unos 3 minutos. No añadas miel, mostaza, limón ni condimentos extra. El aliño puede separarse de nuevo: remueve justo antes de usar y aprovecha todo el contenido. Esta es una versión propuesta de inspiración griega, sin afirmar una fórmula tradicional única.", "image_url": "/recetas/receta-de-ensalada-griega/paso-03.webp", "image_alt": "Ensalada griega propuesta: Prepara el aliño medido"}, {"title": "Mezcla sin romper el feta", "content": "Vierte todo el aliño sobre tomate, pepino, pimiento, cebolla y aceitunas; mezcla suavemente con dos cucharas limpias. Añade todos los dados de feta y da pocas vueltas para conservar su forma. Dedica unos 2 minutos. No añadas lechuga, pan, carne, alcaparras ni más aceite o sal: no están en esta fórmula ni en su cálculo.", "image_url": "/recetas/receta-de-ensalada-griega/paso-04.webp", "image_alt": "Ensalada griega propuesta: Mezcla sin romper el feta"}, {"title": "Enfría tapada", "content": "Pasa toda la ensalada, incluidos jugos y aliño, a un recipiente poco profundo, tapa y refrigera a 4 °C o menos unos 30 minutos, hasta que esté fría; prolonga si lo necesita y suma el tiempo real. Refrigera los perecederos dentro de 2 horas de preparación, o 1 hora si el ambiente supera 32 °C. No dejes el queso ni la ensalada templada esperando fuera del frigorífico.", "image_url": "/recetas/receta-de-ensalada-griega/paso-05.webp", "image_alt": "Ensalada griega propuesta: Enfría tapada"}, {"title": "Reparte y sirve", "content": "Dedica unos 2 minutos a repartir en 4 porciones semejantes, con feta, aceitunas, verduras y todos los jugos y aliño. Los 1292 g son la suma inicial pesada, no un rendimiento final medido. Se proponen 50 minutos completos: preparación 5, corte 8, aliño 3, mezcla 2, frío 30 y reparto 2, sin cocción. Cantidades, tiempos y porciones pendientes de confirmación en cocina. Guarda tapada a 4 °C o menos; consumir en 24 horas es una propuesta de calidad no ensayada, no conservación validada. Saca solo lo que servirás, no reutilices sobras del plato y no juzgues seguridad por olor.", "image_url": "/recetas/receta-de-ensalada-griega/portada.webp", "image_alt": "Ensalada griega propuesta: Reparte y sirve"}], "nutrition": {"calories": 244.9, "protein_g": 7.9, "carbs_g": 13.8, "fat_g": 18.7, "saturated_fat_g": 6.9, "fiber_g": 3.2, "sugar_g": 6.1, "sodium_mg": 710.1, "estimated": true, "source": "USDA FoodData Central — SR Legacy (abril de 2018)", "source_url": "https://fdc.nal.usda.gov/download-datasets/", "inputs": [{"ingredient": "tomate rojo maduro, sin pedúnculo", "edible_grams": 500, "fdc_id": 170457, "fdc_description": "Tomatoes, red, ripe, raw, year round average", "per_100g": {"calories": 18.0, "protein_g": 0.88, "carbs_g": 3.89, "fat_g": 0.2, "saturated_fat_g": 0.028, "fiber_g": 1.2, "sugar_g": 2.63, "sodium_mg": 5.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170457/nutrients"}, {"ingredient": "pepino limpio con piel", "edible_grams": 300, "fdc_id": 168409, "fdc_description": "Cucumber, with peel, raw", "per_100g": {"calories": 15.0, "protein_g": 0.65, "carbs_g": 3.63, "fat_g": 0.11, "saturated_fat_g": 0.037, "fiber_g": 0.5, "sugar_g": 1.67, "sodium_mg": 2.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168409/nutrients"}, {"ingredient": "pimiento verde, sin tallo ni semillas", "edible_grams": 120, "fdc_id": 170427, "fdc_description": "Peppers, sweet, green, raw", "per_100g": {"calories": 20.0, "protein_g": 0.86, "carbs_g": 4.64, "fat_g": 0.17, "saturated_fat_g": 0.058, "fiber_g": 1.7, "sugar_g": 2.4, "sodium_mg": 3.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170427/nutrients"}, {"ingredient": "cebolla roja pelada", "edible_grams": 80, "fdc_id": 170000, "fdc_description": "Onions, raw", "per_100g": {"calories": 40.0, "protein_g": 1.1, "carbs_g": 9.34, "fat_g": 0.1, "saturated_fat_g": 0.042, "fiber_g": 1.7, "sugar_g": 4.24, "sodium_mg": 4.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170000/nutrients"}, {"ingredient": "queso feta entero de leche pasteurizada, escurrido", "edible_grams": 160, "fdc_id": 173420, "fdc_description": "Cheese, feta", "per_100g": {"calories": 265, "protein_g": 14.2, "carbs_g": 3.88, "fat_g": 21.5, "saturated_fat_g": 13.3, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 1140.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173420/nutrients"}, {"ingredient": "aceitunas negras maduras en conserva, sin hueso y escurridas, tamaño pequeño a extragrande", "edible_grams": 80, "fdc_id": 169094, "fdc_description": "Olives, ripe, canned (small-extra large)", "per_100g": {"calories": 116, "protein_g": 0.84, "carbs_g": 6.04, "fat_g": 10.9, "saturated_fat_g": 2.28, "fiber_g": 1.6, "sugar_g": 0.0, "sodium_mg": 735}, "source_url": "https://fdc.nal.usda.gov/food-details/169094/nutrients"}, {"ingredient": "aceite de oliva", "edible_grams": 30, "fdc_id": 171413, "fdc_description": "Oil, olive, salad or cooking", "per_100g": {"calories": 884, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 100, "saturated_fat_g": 13.8, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 2.0}, "source_url": "https://fdc.nal.usda.gov/food-details/171413/nutrients"}, {"ingredient": "vinagre de vino tinto", "edible_grams": 20, "fdc_id": 172240, "fdc_description": "Vinegar, red wine", "per_100g": {"calories": 19.0, "protein_g": 0.04, "carbs_g": 0.27, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 8.0}, "source_url": "https://fdc.nal.usda.gov/food-details/172240/nutrients"}, {"ingredient": "orégano seco", "edible_grams": 1, "fdc_id": 171328, "fdc_description": "Spices, oregano, dried", "per_100g": {"calories": 265, "protein_g": 9.0, "carbs_g": 68.9, "fat_g": 4.28, "saturated_fat_g": 1.55, "fiber_g": 42.5, "sugar_g": 4.09, "sodium_mg": 25.0}, "source_url": "https://fdc.nal.usda.gov/food-details/171328/nutrients"}, {"ingredient": "sal fina", "edible_grams": 1, "fdc_id": 173468, "fdc_description": "Salt, table", "per_100g": {"calories": 0.0, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 38800.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173468/nutrients"}], "serving_size": "Una cuarta parte de la ensalada con todo el aliño; 4 raciones propuestas", "method": "Suma de gramos comestibles por valores USDA por 100 g, dividida entre 4. Diez alimentos exactos y ocho nutrientes informados en todos; datos ausentes nunca inventados.", "note": "Estimación pendiente de confirmación, no análisis ni prueba de cocina. Los 1292 g son peso inicial, no rendimiento final medido. Feta entero USDA genérico, no análisis de una marca pasteurizada concreta. Aceitunas169094 maduras en conserva pequeñas a extragrandes, no Kalamata ni gigantes; 80 g escurridos sin salmuera. Cebolla genérica USDA, no análisis de una variedad roja concreta. Incluye piel comestible, semillas y jugos, los 30 g de aceite, 20 g de vinagre, 1 g de sal y 1 g de orégano. No inventa pérdidas ni reducción de sodio por escurrir. Marcas, agua y sal varían; no incluye acompañamientos."}, "image_url": "/recetas/receta-de-ensalada-griega/portada.webp", "gallery": [{"url": "/recetas/receta-de-ensalada-griega/portada.webp", "alt": "Ensalada de tomate rojo, medias lunas de pepino con piel, pimiento verde, cebolla roja, aceitunas negras y dados de feta, con aliño y orégano sin lechuga"}], "published": false, "editorial_status": "draft", "keywords": ["ensalada griega", "ensalada con feta", "ensalada sin lechuga"], "notes": "Propuesta de inspiración griega con tomate, pepino, pimiento verde, cebolla, feta y aceitunas maduras, sin lechuga; no afirma una fórmula tradicional única. El queso debe ser de leche pasteurizada y conservarse según etiqueta. Contiene leche; revisa ingredientes y trazas de todos los productos. Se calculan aceitunas negras maduras comerciales genéricas de tamaño pequeño a extragrande, no Kalamata ni aceitunas gigantes; elegir otras requiere adaptar y recalcular. El peso de aceitunas y feta es después de escurrir, sin líquido de conserva. Sustituir feta por otro queso o retirarlo cambia sabor, alérgenos y nutrición; no se garantiza equivalencia ni aptitud para alergias. Toda la piel comestible del pepino, semillas y jugos del tomate, aliño y sal se incluyen. No añade pan ni más condimentos. Lava verduras bajo agua corriente sin jabón y utiliza utensilios limpios separados de alimentos crudos que requieran cocción. Mantén a 4 °C o menos y refrigera dentro de 2 horas, o 1 hora por encima de 32 °C. El vinagre no vuelve la ensalada estable a temperatura ambiente. Los 24 horas propuestos son un criterio de calidad no ensayado, no vida útil validada; no se fija congelación. No se afirma prueba de cocina ni beneficio de salud.", "seo": {"title": "Ensalada griega con feta y aceitunas paso a paso", "description": "Tomate, pepino, pimiento, feta y aceitunas: cantidades para cuatro raciones propuestas, aliño medido, frío y conservación explicados.", "image_alt": "Ensalada de tomate rojo, medias lunas de pepino con piel, pimiento verde, cebolla roja, aceitunas negras y dados de feta, con aliño y orégano sin lechuga", "image_variants": ["/recetas/receta-de-ensalada-griega/portada-1x1.webp", "/recetas/receta-de-ensalada-griega/portada-4x3.webp", "/recetas/receta-de-ensalada-griega/portada-16x9.webp"], "faq": [{"q": "¿Lleva lechuga o debe usar aceitunas Kalamata?", "a": "Esta propuesta no lleva lechuga y usa aceitunas negras maduras comerciales para coincidir con la ficha USDA calculada. No las presenta como Kalamata ni como fórmula tradicional única. Cambiar aceitunas modifica sabor y composición y exige revisar cantidades y cálculo."}, {"q": "¿Cómo evito que quede aguada o que el feta se deshaga?", "a": "Seca las verduras tras lavarlas, escurre queso y aceitunas antes de pesar y mezcla el feta al final con pocas vueltas. Conserva los jugos del tomate: forman parte de esta fórmula. Una espera más larga puede soltar más líquido; no se afirma que se haya probado esta textura."}, {"q": "¿Cuánto tarda y cómo se guarda?", "a": "Se proponen 50 minutos, incluidos 30 de frío, sin cocción. Si tarda más en enfriar, suma el tiempo real. Mantén a 4 °C o menos y refrigera dentro de 2 horas, o 1 hora por encima de 32 °C. Consumir en 24 horas es una propuesta de calidad no ensayada; el vinagre no permite dejarla a temperatura ambiente."}]}, "content_html": "<p>Ensalada propuesta de inspiración griega con tomate, pepino, pimiento verde, cebolla, feta pasteurizado y aceitunas negras maduras. Se proponen 4 raciones y 50 minutos completos, incluidos 30 de frío, sin cocción y pendientes de confirmación en cocina.</p><p>Propuesta de inspiración griega con tomate, pepino, pimiento verde, cebolla, feta y aceitunas maduras, sin lechuga; no afirma una fórmula tradicional única. El queso debe ser de leche pasteurizada y conservarse según etiqueta. Contiene leche; revisa ingredientes y trazas de todos los productos. Se calculan aceitunas negras maduras comerciales genéricas de tamaño pequeño a extragrande, no Kalamata ni aceitunas gigantes; elegir otras requiere adaptar y recalcular. El peso de aceitunas y feta es después de escurrir, sin líquido de conserva. Sustituir feta por otro queso o retirarlo cambia sabor, alérgenos y nutrición; no se garantiza equivalencia ni aptitud para alergias. Toda la piel comestible del pepino, semillas y jugos del tomate, aliño y sal se incluyen. No añade pan ni más condimentos. Lava verduras bajo agua corriente sin jabón y utiliza utensilios limpios separados de alimentos crudos que requieran cocción. Mantén a 4 °C o menos y refrigera dentro de 2 horas, o 1 hora por encima de 32 °C. El vinagre no vuelve la ensalada estable a temperatura ambiente. Los 24 horas propuestos son un criterio de calidad no ensayado, no vida útil validada; no se fija congelación. No se afirma prueba de cocina ni beneficio de salud.</p>"}, {"id": "20c36fb6-c385-56d5-8495-ac3e6d112160", "recipe_group_id": "031f1a9c-6240-4ab4-9027-568a18de7ffe", "slug": "griechisches-salat-rezept", "public_path": "/de/griechisches-salat-rezept", "source_url": "https://manualdecocina.com/de/griechisches-salat-rezept/", "language": "de", "title": "Vorschlag für griechischen Salat mit Feta und Oliven", "excerpt": "Tomate, Gurke, Feta und Oliven mit abgewogenem Dressing, ohne Blattsalat und mit Kühlung für vier vorgeschlagene Portionen.", "summary": "Ein Vorschlag für griechisch inspirierten Salat mit Tomate, Gurke, grüner Paprika, Zwiebel, pasteurisiertem Feta und reifen schwarzen Oliven. Vorgesehen sind 4 Portionen und insgesamt 50 Minuten, davon 30 zum Kühlen, ohne Garen. Mengen und Zeiten sind noch in der Küche zu bestätigen.", "category": "Salate", "category_slug": "ensaladas", "difficulty": "Einfach", "course": "Salat", "cuisine": "Griechisch inspiriert", "prep_time_minutes": 20, "cook_time_minutes": 0, "total_time_minutes": 50, "servings": 4, "ingredients": [{"name": "reife rote Tomate ohne Stielansatz", "amount": "500", "unit": "g", "group": "Salat"}, {"name": "saubere Gurke mit Schale", "amount": "300", "unit": "g", "group": "Salat"}, {"name": "grüne Paprika ohne Stiel und Kerne", "amount": "120", "unit": "g", "group": "Salat"}, {"name": "geschälte rote Zwiebel", "amount": "80", "unit": "g", "group": "Salat"}, {"name": "Vollfett-Feta aus pasteurisierter Milch, abgetropft", "amount": "160", "unit": "g", "group": "Salat"}, {"name": "handelsübliche reife schwarze Konservenoliven, entsteint und abgetropft, klein bis extragroß", "amount": "80", "unit": "g", "group": "Salat"}, {"name": "Olivenöl", "amount": "30", "unit": "g", "group": "Dressing"}, {"name": "Rotweinessig", "amount": "20", "unit": "g", "group": "Dressing"}, {"name": "getrockneter Oregano", "amount": "1", "unit": "g", "group": "Dressing"}, {"name": "feines Salz", "amount": "1", "unit": "g", "group": "Dressing"}], "steps": [{"title": "Waschen und abwiegen", "content": "Hände waschen und Waage, Brett, Messer, große Schüssel und Behälter mit Deckel bereitstellen. Tomate, Gurke und Paprika unter fließendem Wasser ohne Seife waschen und trocknen. 500 g Tomate ohne Stielansatz, 300 g Gurke mit Schale, 120 g Paprika ohne Stiel und Kerne und 80 g geschälte Zwiebel abwiegen. 160 g pasteurisierten Feta und 80 g handelsübliche bereits reife, entsteinte schwarze Oliven abtropfen lassen und wiegen; Aufguss nicht verwenden. 30 g Öl, 20 g Essig, 1 g Oregano und 1 g Salz getrennt abwiegen. Etwa 5 Minuten vorsehen und Etiketten von Käse und Oliven beachten; Käse bis zum Schneiden gekühlt halten.", "image_url": "/recetas/receta-de-ensalada-griega/paso-01.webp", "image_alt": "Vorschlag für griechischen Salat mit Feta und Oliven: Waschen und abwiegen"}, {"title": "Gemüse und Käse schneiden", "content": "Tomate in etwa 2 cm große Stücke, Gurke mit Schale in etwa 1 cm dicke Halbmonde, Paprika in Streifen und Zwiebel in feine Scheiben schneiden. Essbare Tomatenkerne und Säfte behalten, Gemüse nicht abtropfen lassen. Feta mit sauberen Geräten würfeln, ohne ihn zu zerbröseln. Prüfen, dass keine Olive einen Stein enthält. Etwa 8 Minuten vorsehen, Gemüse und Oliven in die Schüssel geben und Feta gekühlt zurückstellen.", "image_url": "/recetas/receta-de-ensalada-griega/paso-02.webp", "image_alt": "Vorschlag für griechischen Salat mit Feta und Oliven: Gemüse und Käse schneiden"}, {"title": "Abgewogenes Dressing mischen", "content": "30 g Öl, 20 g Essig, 1 g Oregano und 1 g Salz in einer kleinen Schüssel etwa 3 Minuten vermischen, bis alles verteilt ist. Keinen Honig, Senf, Zitronensaft oder weitere Gewürze hinzufügen. Das Dressing kann sich wieder trennen: unmittelbar vor Verwendung umrühren und vollständig verwenden. Dies ist ein griechisch inspirierter Vorschlag ohne Anspruch auf eine einzige traditionelle Formel.", "image_url": "/recetas/receta-de-ensalada-griega/paso-03.webp", "image_alt": "Vorschlag für griechischen Salat mit Feta und Oliven: Abgewogenes Dressing mischen"}, {"title": "Feta vorsichtig untermischen", "content": "Das gesamte Dressing über Tomate, Gurke, Paprika, Zwiebel und Oliven geben und mit zwei sauberen Löffeln vorsichtig mischen. Alle Fetawürfel hinzufügen und nur wenige Male wenden, damit ihre Form erhalten bleibt. Etwa 2 Minuten vorsehen. Keinen Blattsalat, Brot, Fleisch, Kapern oder zusätzliches Öl und Salz hinzufügen: Sie gehören weder zur Formel noch zur Berechnung.", "image_url": "/recetas/receta-de-ensalada-griega/paso-04.webp", "image_alt": "Vorschlag für griechischen Salat mit Feta und Oliven: Feta vorsichtig untermischen"}, {"title": "Zugedeckt kühlen", "content": "Gesamten Salat einschließlich Säfte und Dressing in einen flachen Behälter geben, abdecken und bei höchstens 4 °C etwa 30 Minuten kühlen, bis er kalt ist; nötigenfalls verlängern und tatsächliche Zeit addieren. Verderbliche Lebensmittel binnen 2 Stunden nach Vorbereitung kühlen, über 32 °C Umgebungstemperatur binnen 1 Stunde. Käse und lauwarmen Salat nicht außerhalb des Kühlschranks warten lassen.", "image_url": "/recetas/receta-de-ensalada-griega/paso-05.webp", "image_alt": "Vorschlag für griechischen Salat mit Feta und Oliven: Zugedeckt kühlen"}, {"title": "Aufteilen und servieren", "content": "Etwa 2 Minuten zum Aufteilen in 4 ähnliche Portionen mit Feta, Oliven, Gemüse und sämtlichen Säften und Dressing vorsehen. 1292 g ist die abgewogene Anfangssumme, keine gemessene fertige Ausbeute. Vorgesehen sind insgesamt 50 Minuten: Vorbereitung 5, Schneiden 8, Dressing 3, Mischen 2, Kühlen 30 und Aufteilen 2, ohne Garen. Mengen, Zeiten und Portionen sind noch in der Küche zu bestätigen. Zugedeckt bei höchstens 4 °C lagern; Verzehr binnen 24 Stunden ist ein ungeprüfter Qualitätsvorschlag, keine validierte Aufbewahrung. Nur die benötigte Menge herausnehmen, Tellerreste nicht wiederverwenden und Sicherheit nicht nach Geruch beurteilen.", "image_url": "/recetas/receta-de-ensalada-griega/portada.webp", "image_alt": "Vorschlag für griechischen Salat mit Feta und Oliven: Aufteilen und servieren"}], "nutrition": {"calories": 244.9, "protein_g": 7.9, "carbs_g": 13.8, "fat_g": 18.7, "saturated_fat_g": 6.9, "fiber_g": 3.2, "sugar_g": 6.1, "sodium_mg": 710.1, "estimated": true, "source": "USDA FoodData Central — SR Legacy", "source_url": "https://fdc.nal.usda.gov/download-datasets/", "inputs": [{"ingredient": "reife rote Tomate ohne Stielansatz", "edible_grams": 500, "fdc_id": 170457, "fdc_description": "Tomatoes, red, ripe, raw, year round average", "per_100g": {"calories": 18.0, "protein_g": 0.88, "carbs_g": 3.89, "fat_g": 0.2, "saturated_fat_g": 0.028, "fiber_g": 1.2, "sugar_g": 2.63, "sodium_mg": 5.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170457/nutrients"}, {"ingredient": "saubere Gurke mit Schale", "edible_grams": 300, "fdc_id": 168409, "fdc_description": "Cucumber, with peel, raw", "per_100g": {"calories": 15.0, "protein_g": 0.65, "carbs_g": 3.63, "fat_g": 0.11, "saturated_fat_g": 0.037, "fiber_g": 0.5, "sugar_g": 1.67, "sodium_mg": 2.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168409/nutrients"}, {"ingredient": "grüne Paprika ohne Stiel und Kerne", "edible_grams": 120, "fdc_id": 170427, "fdc_description": "Peppers, sweet, green, raw", "per_100g": {"calories": 20.0, "protein_g": 0.86, "carbs_g": 4.64, "fat_g": 0.17, "saturated_fat_g": 0.058, "fiber_g": 1.7, "sugar_g": 2.4, "sodium_mg": 3.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170427/nutrients"}, {"ingredient": "geschälte rote Zwiebel", "edible_grams": 80, "fdc_id": 170000, "fdc_description": "Onions, raw", "per_100g": {"calories": 40.0, "protein_g": 1.1, "carbs_g": 9.34, "fat_g": 0.1, "saturated_fat_g": 0.042, "fiber_g": 1.7, "sugar_g": 4.24, "sodium_mg": 4.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170000/nutrients"}, {"ingredient": "Vollfett-Feta aus pasteurisierter Milch, abgetropft", "edible_grams": 160, "fdc_id": 173420, "fdc_description": "Cheese, feta", "per_100g": {"calories": 265, "protein_g": 14.2, "carbs_g": 3.88, "fat_g": 21.5, "saturated_fat_g": 13.3, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 1140.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173420/nutrients"}, {"ingredient": "handelsübliche reife schwarze Konservenoliven, entsteint und abgetropft, klein bis extragroß", "edible_grams": 80, "fdc_id": 169094, "fdc_description": "Olives, ripe, canned (small-extra large)", "per_100g": {"calories": 116, "protein_g": 0.84, "carbs_g": 6.04, "fat_g": 10.9, "saturated_fat_g": 2.28, "fiber_g": 1.6, "sugar_g": 0.0, "sodium_mg": 735}, "source_url": "https://fdc.nal.usda.gov/food-details/169094/nutrients"}, {"ingredient": "Olivenöl", "edible_grams": 30, "fdc_id": 171413, "fdc_description": "Oil, olive, salad or cooking", "per_100g": {"calories": 884, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 100, "saturated_fat_g": 13.8, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 2.0}, "source_url": "https://fdc.nal.usda.gov/food-details/171413/nutrients"}, {"ingredient": "Rotweinessig", "edible_grams": 20, "fdc_id": 172240, "fdc_description": "Vinegar, red wine", "per_100g": {"calories": 19.0, "protein_g": 0.04, "carbs_g": 0.27, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 8.0}, "source_url": "https://fdc.nal.usda.gov/food-details/172240/nutrients"}, {"ingredient": "getrockneter Oregano", "edible_grams": 1, "fdc_id": 171328, "fdc_description": "Spices, oregano, dried", "per_100g": {"calories": 265, "protein_g": 9.0, "carbs_g": 68.9, "fat_g": 4.28, "saturated_fat_g": 1.55, "fiber_g": 42.5, "sugar_g": 4.09, "sodium_mg": 25.0}, "source_url": "https://fdc.nal.usda.gov/food-details/171328/nutrients"}, {"ingredient": "feines Salz", "edible_grams": 1, "fdc_id": 173468, "fdc_description": "Salt, table", "per_100g": {"calories": 0.0, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 38800.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173468/nutrients"}], "serving_size": "Ein Viertel des Salats mit gesamtem Dressing; 4 vorgeschlagene Portionen", "method": "Essbare Gramm mit USDA-Werten je 100 g multiplizieren, summieren und durch 4 teilen. Zehn exakte Lebensmittel mit acht jeweils berichteten Nährwerten; fehlende Angaben werden nie erfunden.", "note": "Noch zu bestätigende Schätzung, keine Analyse oder Küchenprüfung. 1292 g ist Anfangsgewicht, keine gemessene Endausbeute. Allgemeiner USDA-Vollfett-Feta, keine Analyse einer konkreten pasteurisierten Marke. Referenz 169094 für reife Konservenoliven, klein bis extragroß, keine Kalamata oder Riesenoliven; 80 g abgetropft ohne Lake. Allgemeine USDA-Zwiebel, keine Analyse einer bestimmten roten Sorte. Essbare Schale, Kerne und Säfte, sämtliche 30 g Öl, 20 g Essig, 1 g Salz und 1 g Oregano enthalten. Keine erfundenen Verluste oder Natriumreduktion beim Abtropfen. Marke, Feuchtigkeit und Salz variieren; Beilagen ausgeschlossen."}, "image_url": "/recetas/receta-de-ensalada-griega/portada.webp", "gallery": [{"url": "/recetas/receta-de-ensalada-griega/portada.webp", "alt": "Rote Tomate, Gurkenhalbmonde mit Schale, grüne Paprika, rote Zwiebel, schwarze Oliven und Fetawürfel mit Oregano-Dressing ohne Blattsalat"}], "published": false, "editorial_status": "draft", "keywords": ["griechischer Salat", "Salat mit Feta", "Salat ohne Blattsalat"], "notes": "Griechisch inspirierter Vorschlag ohne Blattsalat, ohne Anspruch auf eine einzige traditionelle Formel. Käse aus pasteurisierter Milch verwenden und nach Etikett lagern. Enthält Milch; Zutaten und Spuren aller Produkte prüfen. Berechnet sind allgemeine handelsübliche reife schwarze Konservenoliven, klein bis extragroß, keine Kalamata oder Riesenoliven; andere erfordern Anpassung und Neuberechnung. Feta und Oliven nach Abtropfen ohne Aufguss wiegen. Anderer Käse oder Weglassen verändert Geschmack, Allergene und Nährwerte; weder Gleichwertigkeit noch Allergieverträglichkeit garantiert. Essbare Gurkenschale, Tomatenkerne und Säfte, gesamtes Dressing und Salz sind einbezogen. Kein Brot oder zusätzliche Gewürze. Gemüse unter fließendem Wasser ohne Seife waschen, saubere Geräte getrennt von rohen Lebensmitteln verwenden, die gegart werden müssen. Bei höchstens 4 °C halten und binnen 2 Stunden kühlen, über 32 °C binnen 1 Stunde. Essig macht den Salat nicht bei Raumtemperatur haltbar. Vorgeschlagene 24 Stunden sind ein ungeprüftes Qualitätskriterium, keine validierte Haltbarkeit; keine Gefrierdauer festgelegt. Keine Küchenprüfung oder Gesundheitswirkung behauptet.", "seo": {"title": "Griechischer Salat mit Feta und Oliven: Schritt für Schritt", "description": "Tomate, Gurke, Paprika, Feta und Oliven: Mengen für vier vorgeschlagene Portionen, abgewogenes Dressing, Kühlung und Aufbewahrung.", "image_alt": "Rote Tomate, Gurkenhalbmonde mit Schale, grüne Paprika, rote Zwiebel, schwarze Oliven und Fetawürfel mit Oregano-Dressing ohne Blattsalat", "image_variants": ["/recetas/receta-de-ensalada-griega/portada-1x1.webp", "/recetas/receta-de-ensalada-griega/portada-4x3.webp", "/recetas/receta-de-ensalada-griega/portada-16x9.webp"], "faq": [{"q": "Gehören Blattsalat oder Kalamata-Oliven hinein?", "a": "Dieser Vorschlag enthält keinen Blattsalat und verwendet handelsübliche reife schwarze Oliven passend zur berechneten USDA-Referenz. Sie werden nicht als Kalamata oder einzige traditionelle Formel dargestellt. Andere Oliven verändern Geschmack und Zusammensetzung; Mengen und Berechnung überprüfen."}, {"q": "Wie begrenze ich Flüssigkeit und halte Feta zusammen?", "a": "Gemüse nach Waschen trocknen, Käse und Oliven vor Wiegen abtropfen lassen und Feta zuletzt vorsichtig unterheben. Tomatensäfte behalten: Sie gehören zur Formel. Längere Wartezeit kann mehr Flüssigkeit freisetzen; diese Konsistenz wird nicht als küchenerprobt dargestellt."}, {"q": "Wie lange dauert es und wie wird gelagert?", "a": "Vorgeschlagen sind 50 Minuten, einschließlich 30 Minuten Kühlung, ohne Garen. Reale zusätzliche Kühlzeit addieren. Bei höchstens 4 °C halten und binnen 2 Stunden kühlen, über 32 °C binnen 1 Stunde. Verzehr binnen 24 Stunden ist ein ungeprüfter Qualitätsvorschlag; Essig erlaubt keine Lagerung bei Raumtemperatur."}]}, "content_html": "<p>Ein Vorschlag für griechisch inspirierten Salat mit Tomate, Gurke, grüner Paprika, Zwiebel, pasteurisiertem Feta und reifen schwarzen Oliven. Vorgesehen sind 4 Portionen und insgesamt 50 Minuten, davon 30 zum Kühlen, ohne Garen. Mengen und Zeiten sind noch in der Küche zu bestätigen.</p><p>Griechisch inspirierter Vorschlag ohne Blattsalat, ohne Anspruch auf eine einzige traditionelle Formel. Käse aus pasteurisierter Milch verwenden und nach Etikett lagern. Enthält Milch; Zutaten und Spuren aller Produkte prüfen. Berechnet sind allgemeine handelsübliche reife schwarze Konservenoliven, klein bis extragroß, keine Kalamata oder Riesenoliven; andere erfordern Anpassung und Neuberechnung. Feta und Oliven nach Abtropfen ohne Aufguss wiegen. Anderer Käse oder Weglassen verändert Geschmack, Allergene und Nährwerte; weder Gleichwertigkeit noch Allergieverträglichkeit garantiert. Essbare Gurkenschale, Tomatenkerne und Säfte, gesamtes Dressing und Salz sind einbezogen. Kein Brot oder zusätzliche Gewürze. Gemüse unter fließendem Wasser ohne Seife waschen, saubere Geräte getrennt von rohen Lebensmitteln verwenden, die gegart werden müssen. Bei höchstens 4 °C halten und binnen 2 Stunden kühlen, über 32 °C binnen 1 Stunde. Essig macht den Salat nicht bei Raumtemperatur haltbar. Vorgeschlagene 24 Stunden sind ein ungeprüftes Qualitätskriterium, keine validierte Haltbarkeit; keine Gefrierdauer festgelegt. Keine Küchenprüfung oder Gesundheitswirkung behauptet.</p>"}, {"id": "79089569-82a8-505b-b01c-de09688fe74a", "recipe_group_id": "031f1a9c-6240-4ab4-9027-568a18de7ffe", "slug": "greek-salad-recipe", "public_path": "/en/greek-salad-recipe", "source_url": null, "language": "en", "title": "Proposed Greek salad with feta and olives", "excerpt": "Tomato, cucumber, feta and olives with a measured dressing, no lettuce and chilling included for four proposed servings.", "summary": "A proposed Greek-inspired salad with tomato, cucumber, green pepper, onion, pasteurized feta and ripe black olives. A proposed 4 servings and 50 complete minutes, including 30 minutes chilling, with no cooking; quantities and timings await kitchen confirmation.", "category": "Salads", "category_slug": "ensaladas", "difficulty": "Easy", "course": "Salad", "cuisine": "Greek-inspired", "prep_time_minutes": 20, "cook_time_minutes": 0, "total_time_minutes": 50, "servings": 4, "ingredients": [{"name": "ripe red tomato without stem", "amount": "500", "unit": "g", "group": "Salad"}, {"name": "clean cucumber with peel", "amount": "300", "unit": "g", "group": "Salad"}, {"name": "green pepper without stem or seeds", "amount": "120", "unit": "g", "group": "Salad"}, {"name": "peeled red onion", "amount": "80", "unit": "g", "group": "Salad"}, {"name": "full-fat feta made with pasteurized milk, drained", "amount": "160", "unit": "g", "group": "Salad"}, {"name": "commercial canned ripe black olives, pitted and drained, small to extra-large", "amount": "80", "unit": "g", "group": "Salad"}, {"name": "olive oil", "amount": "30", "unit": "g", "group": "Dressing"}, {"name": "red wine vinegar", "amount": "20", "unit": "g", "group": "Dressing"}, {"name": "dried oregano", "amount": "1", "unit": "g", "group": "Dressing"}, {"name": "fine salt", "amount": "1", "unit": "g", "group": "Dressing"}], "steps": [{"title": "Wash and weigh", "content": "Wash your hands and prepare scales, a board, knife, large bowl and lidded container. Wash tomato, cucumber and pepper under running water without soap, then dry. Weigh 500 g tomato without stem, 300 g cucumber with peel, 120 g pepper without stem or seeds and 80 g peeled onion. Drain and weigh 160 g pasteurized feta and 80 g commercially canned ripe pitted black olives; exclude the packing liquid. Separately weigh 30 g oil, 20 g vinegar, 1 g oregano and 1 g salt. Allow about 5 minutes and follow cheese and olive labels; keep cheese refrigerated until cutting.", "image_url": "/recetas/receta-de-ensalada-griega/paso-01.webp", "image_alt": "Proposed Greek salad with feta and olives: Wash and weigh"}, {"title": "Cut vegetables and cheese", "content": "Cut tomato into approximately 2 cm pieces, cucumber with peel into half-moons approximately 1 cm thick, pepper into strips and onion into thin slices. Retain edible tomato seeds and juices without draining the vegetables. Cube feta using clean utensils without crumbling it. Check that all olives are pitted. Allow about 8 minutes and gather vegetables and olives in the bowl; keep feta chilled.", "image_url": "/recetas/receta-de-ensalada-griega/paso-02.webp", "image_alt": "Proposed Greek salad with feta and olives: Cut vegetables and cheese"}, {"title": "Mix the measured dressing", "content": "Mix the 30 g oil, 20 g vinegar, 1 g oregano and 1 g salt in a small bowl until dispersed, for about 3 minutes. Do not add honey, mustard, lemon or extra seasonings. The dressing may separate again: stir immediately before use and use all of it. This is a proposed Greek-inspired version without claiming a single traditional formula.", "image_url": "/recetas/receta-de-ensalada-griega/paso-03.webp", "image_alt": "Proposed Greek salad with feta and olives: Mix the measured dressing"}, {"title": "Mix without breaking the feta", "content": "Pour all dressing over tomato, cucumber, pepper, onion and olives; gently mix with two clean spoons. Add all feta cubes and turn only a few times to preserve their shape. Allow about 2 minutes. Do not add lettuce, bread, meat, capers or extra oil or salt: they are outside this formula and its calculation.", "image_url": "/recetas/receta-de-ensalada-griega/paso-04.webp", "image_alt": "Proposed Greek salad with feta and olives: Mix without breaking the feta"}, {"title": "Chill covered", "content": "Transfer all salad, including juices and dressing, to a shallow container, cover and refrigerate at 4 °C or below for about 30 minutes until cold; extend if needed and include the actual time. Refrigerate perishables within 2 hours of preparation, or 1 hour if ambient temperature exceeds 32 °C. Do not leave cheese or lukewarm salad waiting outside the refrigerator.", "image_url": "/recetas/receta-de-ensalada-griega/paso-05.webp", "image_alt": "Proposed Greek salad with feta and olives: Chill covered"}, {"title": "Divide and serve", "content": "Allow about 2 minutes to divide into 4 similar portions containing feta, olives, vegetables and all juices and dressing. The 1292 g is the initial weighed sum, not a measured final yield. A proposed 50 complete minutes comprises preparation 5, cutting 8, dressing 3, mixing 2, chilling 30 and dividing 2, without cooking. Quantities, timings and servings await kitchen confirmation. Store covered at 4 °C or below; eating within 24 hours is an untested quality proposal, not validated storage. Take out only what you will serve, do not reuse plate leftovers and do not judge safety by smell.", "image_url": "/recetas/receta-de-ensalada-griega/portada.webp", "image_alt": "Proposed Greek salad with feta and olives: Divide and serve"}], "nutrition": {"calories": 244.9, "protein_g": 7.9, "carbs_g": 13.8, "fat_g": 18.7, "saturated_fat_g": 6.9, "fiber_g": 3.2, "sugar_g": 6.1, "sodium_mg": 710.1, "estimated": true, "source": "USDA FoodData Central — SR Legacy", "source_url": "https://fdc.nal.usda.gov/download-datasets/", "inputs": [{"ingredient": "ripe red tomato without stem", "edible_grams": 500, "fdc_id": 170457, "fdc_description": "Tomatoes, red, ripe, raw, year round average", "per_100g": {"calories": 18.0, "protein_g": 0.88, "carbs_g": 3.89, "fat_g": 0.2, "saturated_fat_g": 0.028, "fiber_g": 1.2, "sugar_g": 2.63, "sodium_mg": 5.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170457/nutrients"}, {"ingredient": "clean cucumber with peel", "edible_grams": 300, "fdc_id": 168409, "fdc_description": "Cucumber, with peel, raw", "per_100g": {"calories": 15.0, "protein_g": 0.65, "carbs_g": 3.63, "fat_g": 0.11, "saturated_fat_g": 0.037, "fiber_g": 0.5, "sugar_g": 1.67, "sodium_mg": 2.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168409/nutrients"}, {"ingredient": "green pepper without stem or seeds", "edible_grams": 120, "fdc_id": 170427, "fdc_description": "Peppers, sweet, green, raw", "per_100g": {"calories": 20.0, "protein_g": 0.86, "carbs_g": 4.64, "fat_g": 0.17, "saturated_fat_g": 0.058, "fiber_g": 1.7, "sugar_g": 2.4, "sodium_mg": 3.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170427/nutrients"}, {"ingredient": "peeled red onion", "edible_grams": 80, "fdc_id": 170000, "fdc_description": "Onions, raw", "per_100g": {"calories": 40.0, "protein_g": 1.1, "carbs_g": 9.34, "fat_g": 0.1, "saturated_fat_g": 0.042, "fiber_g": 1.7, "sugar_g": 4.24, "sodium_mg": 4.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170000/nutrients"}, {"ingredient": "full-fat feta made with pasteurized milk, drained", "edible_grams": 160, "fdc_id": 173420, "fdc_description": "Cheese, feta", "per_100g": {"calories": 265, "protein_g": 14.2, "carbs_g": 3.88, "fat_g": 21.5, "saturated_fat_g": 13.3, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 1140.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173420/nutrients"}, {"ingredient": "commercial canned ripe black olives, pitted and drained, small to extra-large", "edible_grams": 80, "fdc_id": 169094, "fdc_description": "Olives, ripe, canned (small-extra large)", "per_100g": {"calories": 116, "protein_g": 0.84, "carbs_g": 6.04, "fat_g": 10.9, "saturated_fat_g": 2.28, "fiber_g": 1.6, "sugar_g": 0.0, "sodium_mg": 735}, "source_url": "https://fdc.nal.usda.gov/food-details/169094/nutrients"}, {"ingredient": "olive oil", "edible_grams": 30, "fdc_id": 171413, "fdc_description": "Oil, olive, salad or cooking", "per_100g": {"calories": 884, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 100, "saturated_fat_g": 13.8, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 2.0}, "source_url": "https://fdc.nal.usda.gov/food-details/171413/nutrients"}, {"ingredient": "red wine vinegar", "edible_grams": 20, "fdc_id": 172240, "fdc_description": "Vinegar, red wine", "per_100g": {"calories": 19.0, "protein_g": 0.04, "carbs_g": 0.27, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 8.0}, "source_url": "https://fdc.nal.usda.gov/food-details/172240/nutrients"}, {"ingredient": "dried oregano", "edible_grams": 1, "fdc_id": 171328, "fdc_description": "Spices, oregano, dried", "per_100g": {"calories": 265, "protein_g": 9.0, "carbs_g": 68.9, "fat_g": 4.28, "saturated_fat_g": 1.55, "fiber_g": 42.5, "sugar_g": 4.09, "sodium_mg": 25.0}, "source_url": "https://fdc.nal.usda.gov/food-details/171328/nutrients"}, {"ingredient": "fine salt", "edible_grams": 1, "fdc_id": 173468, "fdc_description": "Salt, table", "per_100g": {"calories": 0.0, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 38800.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173468/nutrients"}], "serving_size": "One quarter of the salad with all its dressing; 4 proposed servings", "method": "Sum edible grams multiplied by USDA values per 100 g, divided by 4. Ten exact foods and eight nutrients reported for every food; missing data are never invented.", "note": "Estimate awaiting confirmation, not analysis or kitchen testing. 1292 g is initial weight, not measured final yield. Generic USDA full-fat feta, not analysis of a particular pasteurized brand. Ripe canned olives reference 169094, small to extra-large, not Kalamata or jumbo; 80 g drained without brine. Generic USDA onion, not analysis of a specific red variety. Includes edible peel, seeds and juices, all 30 g oil, 20 g vinegar, 1 g salt and 1 g oregano. No invented losses or sodium reduction from draining. Brands, moisture and salt vary; accompaniments excluded."}, "image_url": "/recetas/receta-de-ensalada-griega/portada.webp", "gallery": [{"url": "/recetas/receta-de-ensalada-griega/portada.webp", "alt": "Red tomato, cucumber half-moons with peel, green pepper, red onion, black olives and feta cubes with oregano dressing, without lettuce"}], "published": false, "editorial_status": "draft", "keywords": ["Greek salad", "feta salad", "salad without lettuce"], "notes": "A Greek-inspired proposal without lettuce; no claim to one traditional formula. Feta must be made with pasteurized milk and kept according to its label. Contains milk; check all ingredients and cross-contact information. The calculation uses generic commercial canned ripe black olives, small to extra-large, not Kalamata or jumbo olives; changing them requires adjustment and recalculation. Weigh feta and olives after draining, without packing liquid. Replacing or omitting feta changes flavor, allergens and nutrition; equivalent results or suitability for allergies are not guaranteed. All edible cucumber peel, tomato seeds and juices, dressing and salt are included. No bread or extra seasonings. Wash vegetables under running water without soap and use clean utensils separate from raw foods requiring cooking. Keep at 4 °C or below and refrigerate within 2 hours, or 1 hour above 32 °C. Vinegar does not make the salad stable at room temperature. The proposed 24 hours is an untested quality criterion, not validated shelf life; no freezing period is specified. No kitchen testing or health benefit is claimed.", "seo": {"title": "Greek salad with feta and olives, step by step", "description": "Tomato, cucumber, green pepper, feta and olives: quantities for four proposed servings, measured dressing, chilling and storage explained.", "image_alt": "Red tomato, cucumber half-moons with peel, green pepper, red onion, black olives and feta cubes with oregano dressing, without lettuce", "image_variants": ["/recetas/receta-de-ensalada-griega/portada-1x1.webp", "/recetas/receta-de-ensalada-griega/portada-4x3.webp", "/recetas/receta-de-ensalada-griega/portada-16x9.webp"], "faq": [{"q": "Does it contain lettuce or require Kalamata olives?", "a": "This proposal has no lettuce and uses commercial ripe black olives to match the calculated USDA reference. They are not presented as Kalamata or as a single traditional formula. Different olives change flavor and composition and require a review of quantities and calculation."}, {"q": "How can I limit excess liquid and keep feta intact?", "a": "Dry vegetables after washing, drain cheese and olives before weighing, and gently fold feta in last. Retain tomato juices: they belong to this formula. A longer wait may release more liquid; this texture has not been claimed as kitchen-tested."}, {"q": "How long does it take and how is it stored?", "a": "A proposed 50 minutes includes 30 minutes chilling, with no cooking. Add actual extra chilling time. Keep at 4 °C or below and refrigerate within 2 hours, or 1 hour above 32 °C. Eating within 24 hours is an untested quality proposal; vinegar does not permit room-temperature storage."}]}, "content_html": "<p>A proposed Greek-inspired salad with tomato, cucumber, green pepper, onion, pasteurized feta and ripe black olives. A proposed 4 servings and 50 complete minutes, including 30 minutes chilling, with no cooking; quantities and timings await kitchen confirmation.</p><p>A Greek-inspired proposal without lettuce; no claim to one traditional formula. Feta must be made with pasteurized milk and kept according to its label. Contains milk; check all ingredients and cross-contact information. The calculation uses generic commercial canned ripe black olives, small to extra-large, not Kalamata or jumbo olives; changing them requires adjustment and recalculation. Weigh feta and olives after draining, without packing liquid. Replacing or omitting feta changes flavor, allergens and nutrition; equivalent results or suitability for allergies are not guaranteed. All edible cucumber peel, tomato seeds and juices, dressing and salt are included. No bread or extra seasonings. Wash vegetables under running water without soap and use clean utensils separate from raw foods requiring cooking. Keep at 4 °C or below and refrigerate within 2 hours, or 1 hour above 32 °C. Vinegar does not make the salad stable at room temperature. The proposed 24 hours is an untested quality criterion, not validated shelf life; no freezing period is specified. No kitchen testing or health benefit is claimed.</p>"}, {"id": "d77947db-81d5-5372-a492-160800465554", "recipe_group_id": "031f1a9c-6240-4ab4-9027-568a18de7ffe", "slug": "recette-de-salade-grecque", "public_path": "/fr/recette-de-salade-grecque", "source_url": "https://manualdecocina.com/fr/recette-de-salade-grecque/", "language": "fr", "title": "Proposition de salade grecque à la feta et aux olives", "excerpt": "Tomate, concombre, feta et olives avec une sauce pesée, sans laitue et avec réfrigération pour quatre portions proposées.", "summary": "Une proposition de salade inspirée de la cuisine grecque : tomate, concombre, poivron vert, oignon, feta pasteurisée et olives noires mûres. On propose 4 portions et 50 minutes au total, dont 30 au froid, sans cuisson. Quantités et durées restent à confirmer en cuisine.", "category": "Salades", "category_slug": "ensaladas", "difficulty": "Facile", "course": "Salade", "cuisine": "Inspiration grecque", "prep_time_minutes": 20, "cook_time_minutes": 0, "total_time_minutes": 50, "servings": 4, "ingredients": [{"name": "tomate rouge mûre sans pédoncule", "amount": "500", "unit": "g", "group": "Salade"}, {"name": "concombre propre avec sa peau", "amount": "300", "unit": "g", "group": "Salade"}, {"name": "poivron vert sans pédoncule ni graines", "amount": "120", "unit": "g", "group": "Salade"}, {"name": "oignon rouge épluché", "amount": "80", "unit": "g", "group": "Salade"}, {"name": "feta entière au lait pasteurisé, égouttée", "amount": "160", "unit": "g", "group": "Salade"}, {"name": "olives noires mûres en conserve du commerce, dénoyautées et égouttées, petites à extra-grosses", "amount": "80", "unit": "g", "group": "Salade"}, {"name": "huile d’olive", "amount": "30", "unit": "g", "group": "Assaisonnement"}, {"name": "vinaigre de vin rouge", "amount": "20", "unit": "g", "group": "Assaisonnement"}, {"name": "origan séché", "amount": "1", "unit": "g", "group": "Assaisonnement"}, {"name": "sel fin", "amount": "1", "unit": "g", "group": "Assaisonnement"}], "steps": [{"title": "Laver et peser", "content": "Lavez-vous les mains et préparez balance, planche, couteau, grand saladier et récipient avec couvercle. Lavez tomate, concombre et poivron sous l’eau courante sans savon, puis séchez. Pesez 500 g de tomate sans pédoncule, 300 g de concombre avec sa peau, 120 g de poivron sans pédoncule ni graines et 80 g d’oignon épluché. Égouttez et pesez 160 g de feta pasteurisée et 80 g d’olives noires mûres du commerce, dénoyautées ; excluez le liquide de conserve. Pesez séparément 30 g d’huile, 20 g de vinaigre, 1 g d’origan et 1 g de sel. Prévoyez environ 5 minutes et respectez les étiquettes du fromage et des olives ; gardez le fromage au froid jusqu’à la découpe.", "image_url": "/recetas/receta-de-ensalada-griega/paso-01.webp", "image_alt": "Proposition de salade grecque à la feta et aux olives: Laver et peser"}, {"title": "Couper les légumes et le fromage", "content": "Coupez la tomate en morceaux d’environ 2 cm, le concombre avec sa peau en demi-rondelles d’environ 1 cm, le poivron en lanières et l’oignon en fines lamelles. Conservez les graines comestibles et le jus de tomate, sans égoutter les légumes. Coupez la feta en dés avec des ustensiles propres, sans l’émietter. Vérifiez qu’aucune olive ne contient de noyau. Prévoyez environ 8 minutes, réunissez légumes et olives dans le saladier et réservez la feta au froid.", "image_url": "/recetas/receta-de-ensalada-griega/paso-02.webp", "image_alt": "Proposition de salade grecque à la feta et aux olives: Couper les légumes et le fromage"}, {"title": "Préparer l’assaisonnement pesé", "content": "Mélangez dans un petit bol les 30 g d’huile, les 20 g de vinaigre, le 1 g d’origan et le 1 g de sel jusqu’à dispersion, pendant environ 3 minutes. N’ajoutez ni miel, ni moutarde, ni citron, ni autre condiment. Le mélange peut se séparer à nouveau : remuez juste avant usage et utilisez tout le contenu. Cette version proposée est d’inspiration grecque, sans prétendre à une formule traditionnelle unique.", "image_url": "/recetas/receta-de-ensalada-griega/paso-03.webp", "image_alt": "Proposition de salade grecque à la feta et aux olives: Préparer l’assaisonnement pesé"}, {"title": "Mélanger sans briser la feta", "content": "Versez tout l’assaisonnement sur tomate, concombre, poivron, oignon et olives ; mélangez délicatement avec deux cuillères propres. Ajoutez tous les dés de feta et tournez peu pour préserver leur forme. Prévoyez environ 2 minutes. N’ajoutez ni laitue, ni pain, ni viande, ni câpres, ni huile ou sel supplémentaires : ils ne font pas partie de cette formule ni de son calcul.", "image_url": "/recetas/receta-de-ensalada-griega/paso-04.webp", "image_alt": "Proposition de salade grecque à la feta et aux olives: Mélanger sans briser la feta"}, {"title": "Réfrigérer à couvert", "content": "Transférez toute la salade, jus et sauce compris, dans un récipient peu profond, couvrez et réfrigérez à 4 °C ou moins pendant environ 30 minutes, jusqu’à refroidissement ; prolongez si nécessaire et ajoutez la durée réelle. Réfrigérez les aliments périssables dans les 2 heures suivant la préparation, ou dans l’heure, soit 1 heure, si la température ambiante dépasse 32 °C. Ne laissez pas le fromage ou la salade tiède attendre hors du réfrigérateur.", "image_url": "/recetas/receta-de-ensalada-griega/paso-05.webp", "image_alt": "Proposition de salade grecque à la feta et aux olives: Réfrigérer à couvert"}, {"title": "Répartir et servir", "content": "Prévoyez environ 2 minutes pour répartir en 4 portions similaires avec feta, olives, légumes et tout le jus et l’assaisonnement. Les 1292 g représentent la somme initialement pesée, pas un rendement final mesuré. On propose 50 minutes au total : préparation 5, découpe 8, sauce 3, mélange 2, froid 30 et répartition 2, sans cuisson. Quantités, durées et portions restent à confirmer en cuisine. Conservez à couvert à 4 °C ou moins ; consommer dans les 24 heures est une proposition de qualité non testée, pas une conservation validée. Sortez seulement ce qui sera servi, ne réutilisez pas les restes d’assiette et ne jugez pas la sécurité à l’odeur.", "image_url": "/recetas/receta-de-ensalada-griega/portada.webp", "image_alt": "Proposition de salade grecque à la feta et aux olives: Répartir et servir"}], "nutrition": {"calories": 244.9, "protein_g": 7.9, "carbs_g": 13.8, "fat_g": 18.7, "saturated_fat_g": 6.9, "fiber_g": 3.2, "sugar_g": 6.1, "sodium_mg": 710.1, "estimated": true, "source": "USDA FoodData Central — SR Legacy", "source_url": "https://fdc.nal.usda.gov/download-datasets/", "inputs": [{"ingredient": "tomate rouge mûre sans pédoncule", "edible_grams": 500, "fdc_id": 170457, "fdc_description": "Tomatoes, red, ripe, raw, year round average", "per_100g": {"calories": 18.0, "protein_g": 0.88, "carbs_g": 3.89, "fat_g": 0.2, "saturated_fat_g": 0.028, "fiber_g": 1.2, "sugar_g": 2.63, "sodium_mg": 5.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170457/nutrients"}, {"ingredient": "concombre propre avec sa peau", "edible_grams": 300, "fdc_id": 168409, "fdc_description": "Cucumber, with peel, raw", "per_100g": {"calories": 15.0, "protein_g": 0.65, "carbs_g": 3.63, "fat_g": 0.11, "saturated_fat_g": 0.037, "fiber_g": 0.5, "sugar_g": 1.67, "sodium_mg": 2.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168409/nutrients"}, {"ingredient": "poivron vert sans pédoncule ni graines", "edible_grams": 120, "fdc_id": 170427, "fdc_description": "Peppers, sweet, green, raw", "per_100g": {"calories": 20.0, "protein_g": 0.86, "carbs_g": 4.64, "fat_g": 0.17, "saturated_fat_g": 0.058, "fiber_g": 1.7, "sugar_g": 2.4, "sodium_mg": 3.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170427/nutrients"}, {"ingredient": "oignon rouge épluché", "edible_grams": 80, "fdc_id": 170000, "fdc_description": "Onions, raw", "per_100g": {"calories": 40.0, "protein_g": 1.1, "carbs_g": 9.34, "fat_g": 0.1, "saturated_fat_g": 0.042, "fiber_g": 1.7, "sugar_g": 4.24, "sodium_mg": 4.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170000/nutrients"}, {"ingredient": "feta entière au lait pasteurisé, égouttée", "edible_grams": 160, "fdc_id": 173420, "fdc_description": "Cheese, feta", "per_100g": {"calories": 265, "protein_g": 14.2, "carbs_g": 3.88, "fat_g": 21.5, "saturated_fat_g": 13.3, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 1140.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173420/nutrients"}, {"ingredient": "olives noires mûres en conserve du commerce, dénoyautées et égouttées, petites à extra-grosses", "edible_grams": 80, "fdc_id": 169094, "fdc_description": "Olives, ripe, canned (small-extra large)", "per_100g": {"calories": 116, "protein_g": 0.84, "carbs_g": 6.04, "fat_g": 10.9, "saturated_fat_g": 2.28, "fiber_g": 1.6, "sugar_g": 0.0, "sodium_mg": 735}, "source_url": "https://fdc.nal.usda.gov/food-details/169094/nutrients"}, {"ingredient": "huile d’olive", "edible_grams": 30, "fdc_id": 171413, "fdc_description": "Oil, olive, salad or cooking", "per_100g": {"calories": 884, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 100, "saturated_fat_g": 13.8, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 2.0}, "source_url": "https://fdc.nal.usda.gov/food-details/171413/nutrients"}, {"ingredient": "vinaigre de vin rouge", "edible_grams": 20, "fdc_id": 172240, "fdc_description": "Vinegar, red wine", "per_100g": {"calories": 19.0, "protein_g": 0.04, "carbs_g": 0.27, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 8.0}, "source_url": "https://fdc.nal.usda.gov/food-details/172240/nutrients"}, {"ingredient": "origan séché", "edible_grams": 1, "fdc_id": 171328, "fdc_description": "Spices, oregano, dried", "per_100g": {"calories": 265, "protein_g": 9.0, "carbs_g": 68.9, "fat_g": 4.28, "saturated_fat_g": 1.55, "fiber_g": 42.5, "sugar_g": 4.09, "sodium_mg": 25.0}, "source_url": "https://fdc.nal.usda.gov/food-details/171328/nutrients"}, {"ingredient": "sel fin", "edible_grams": 1, "fdc_id": 173468, "fdc_description": "Salt, table", "per_100g": {"calories": 0.0, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 38800.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173468/nutrients"}], "serving_size": "Un quart de la salade avec tout son assaisonnement ; 4 portions proposées", "method": "Somme des grammes comestibles multipliés par les valeurs USDA pour 100 g, divisée par 4. Dix aliments exacts et huit nutriments renseignés pour chacun ; aucune donnée manquante inventée.", "note": "Estimation à confirmer, sans analyse ni essai en cuisine. Les 1292 g sont le poids initial, pas un rendement final mesuré. Feta entière générique USDA, pas analyse d’une marque pasteurisée particulière. Référence 169094 : olives mûres en conserve petites à extra-grosses, pas Kalamata ni géantes ; 80 g égouttées sans saumure. Oignon générique USDA, pas analyse d’une variété rouge précise. Peau comestible, graines, jus, totalité des 30 g d’huile, 20 g de vinaigre, 1 g de sel et 1 g d’origan inclus. Aucune perte ou réduction de sodium par égouttage inventée. Marques, humidité et sel varient ; accompagnements exclus."}, "image_url": "/recetas/receta-de-ensalada-griega/portada.webp", "gallery": [{"url": "/recetas/receta-de-ensalada-griega/portada.webp", "alt": "Tomate rouge, demi-rondelles de concombre avec peau, poivron vert, oignon rouge, olives noires et dés de feta avec sauce à l’origan, sans laitue"}], "published": false, "editorial_status": "draft", "keywords": ["salade grecque", "salade à la feta", "salade sans laitue"], "notes": "Proposition d’inspiration grecque sans laitue, sans revendiquer une formule traditionnelle unique. Utilisez du fromage au lait pasteurisé et respectez son étiquette. Contient du lait ; vérifiez tous les ingrédients et risques de traces. Le calcul emploie des olives noires mûres en conserve génériques du commerce, petites à extra-grosses, pas des Kalamata ni des olives géantes ; un changement exige adaptation et nouveau calcul. Pesez feta et olives après égouttage, sans liquide de conserve. Remplacer ou supprimer la feta modifie goût, allergènes et nutrition ; aucune équivalence ni compatibilité avec les allergies n’est garantie. Toute la peau comestible du concombre, les graines et le jus de tomate, la sauce et le sel sont inclus. Aucun pain ou condiment supplémentaire. Lavez les légumes à l’eau courante sans savon et utilisez des ustensiles propres séparés des aliments crus à cuire. Gardez à 4 °C ou moins et réfrigérez dans les 2 heures, ou 1 heure au-dessus de 32 °C. Le vinaigre ne stabilise pas la salade à température ambiante. Les 24 heures proposées sont un critère de qualité non testé, pas une durée de conservation validée ; aucune durée de congélation n’est fixée. Aucun essai en cuisine ni bénéfice santé n’est affirmé.", "seo": {"title": "Salade grecque à la feta et aux olives, étape par étape", "description": "Tomate, concombre, poivron, feta et olives : quantités pour quatre portions proposées, assaisonnement pesé, froid et conservation expliqués.", "image_alt": "Tomate rouge, demi-rondelles de concombre avec peau, poivron vert, oignon rouge, olives noires et dés de feta avec sauce à l’origan, sans laitue", "image_variants": ["/recetas/receta-de-ensalada-griega/portada-1x1.webp", "/recetas/receta-de-ensalada-griega/portada-4x3.webp", "/recetas/receta-de-ensalada-griega/portada-16x9.webp"], "faq": [{"q": "Faut-il de la laitue ou des olives Kalamata ?", "a": "Cette proposition ne contient pas de laitue et emploie des olives noires mûres du commerce correspondant à la fiche USDA calculée. Elles ne sont pas présentées comme des Kalamata ni comme une formule traditionnelle unique. Changer d’olives modifie goût et composition ; revoyez quantités et calcul."}, {"q": "Comment limiter le liquide et garder la feta intacte ?", "a": "Séchez les légumes lavés, égouttez fromage et olives avant pesée et ajoutez la feta délicatement en dernier. Gardez le jus de tomate : il appartient à cette formule. Une attente prolongée peut libérer davantage de liquide ; cette texture n’est pas présentée comme testée en cuisine."}, {"q": "Quelle durée prévoir et comment conserver ?", "a": "On propose 50 minutes, dont 30 au froid, sans cuisson. Ajoutez tout temps réel de refroidissement supplémentaire. Gardez à 4 °C ou moins et réfrigérez dans les 2 heures, ou 1 heure au-dessus de 32 °C. Consommer dans les 24 heures est une proposition de qualité non testée ; le vinaigre n’autorise pas la conservation à température ambiante."}]}, "content_html": "<p>Une proposition de salade inspirée de la cuisine grecque : tomate, concombre, poivron vert, oignon, feta pasteurisée et olives noires mûres. On propose 4 portions et 50 minutes au total, dont 30 au froid, sans cuisson. Quantités et durées restent à confirmer en cuisine.</p><p>Proposition d’inspiration grecque sans laitue, sans revendiquer une formule traditionnelle unique. Utilisez du fromage au lait pasteurisé et respectez son étiquette. Contient du lait ; vérifiez tous les ingrédients et risques de traces. Le calcul emploie des olives noires mûres en conserve génériques du commerce, petites à extra-grosses, pas des Kalamata ni des olives géantes ; un changement exige adaptation et nouveau calcul. Pesez feta et olives après égouttage, sans liquide de conserve. Remplacer ou supprimer la feta modifie goût, allergènes et nutrition ; aucune équivalence ni compatibilité avec les allergies n’est garantie. Toute la peau comestible du concombre, les graines et le jus de tomate, la sauce et le sel sont inclus. Aucun pain ou condiment supplémentaire. Lavez les légumes à l’eau courante sans savon et utilisez des ustensiles propres séparés des aliments crus à cuire. Gardez à 4 °C ou moins et réfrigérez dans les 2 heures, ou 1 heure au-dessus de 32 °C. Le vinaigre ne stabilise pas la salade à température ambiante. Les 24 heures proposées sont un critère de qualité non testé, pas une durée de conservation validée ; aucune durée de congélation n’est fixée. Aucun essai en cuisine ni bénéfice santé n’est affirmé.</p>"}, {"id": "38e6dca6-a6b1-5a09-8593-7baa1cc80195", "recipe_group_id": "031f1a9c-6240-4ab4-9027-568a18de7ffe", "slug": "ricetta-insalata-greca", "public_path": "/it/ricetta-insalata-greca", "source_url": "https://manualdecocina.com/it/ricetta-insalata-greca/", "language": "it", "title": "Proposta di insalata greca con feta e olive", "excerpt": "Pomodoro, cetriolo, feta e olive con condimento pesato, senza lattuga e con raffreddamento incluso per quattro porzioni proposte.", "summary": "Una proposta di insalata d’ispirazione greca con pomodoro, cetriolo, peperone verde, cipolla, feta pastorizzata e olive nere mature. Si propongono 4 porzioni e 50 minuti complessivi, di cui 30 al freddo, senza cottura. Quantità e tempi attendono conferma in cucina.", "category": "Insalate", "category_slug": "ensaladas", "difficulty": "Facile", "course": "Insalata", "cuisine": "Ispirazione greca", "prep_time_minutes": 20, "cook_time_minutes": 0, "total_time_minutes": 50, "servings": 4, "ingredients": [{"name": "pomodoro rosso maturo senza peduncolo", "amount": "500", "unit": "g", "group": "Insalata"}, {"name": "cetriolo pulito con buccia", "amount": "300", "unit": "g", "group": "Insalata"}, {"name": "peperone verde senza picciolo né semi", "amount": "120", "unit": "g", "group": "Insalata"}, {"name": "cipolla rossa sbucciata", "amount": "80", "unit": "g", "group": "Insalata"}, {"name": "feta intera da latte pastorizzato, scolata", "amount": "160", "unit": "g", "group": "Insalata"}, {"name": "olive nere mature in conserva commerciale, denocciolate e scolate, da piccole a extra-grandi", "amount": "80", "unit": "g", "group": "Insalata"}, {"name": "olio d’oliva", "amount": "30", "unit": "g", "group": "Condimento"}, {"name": "aceto di vino rosso", "amount": "20", "unit": "g", "group": "Condimento"}, {"name": "origano secco", "amount": "1", "unit": "g", "group": "Condimento"}, {"name": "sale fino", "amount": "1", "unit": "g", "group": "Condimento"}], "steps": [{"title": "Lavare e pesare", "content": "Lava le mani e prepara bilancia, tagliere, coltello, ciotola grande e contenitore con coperchio. Lava pomodoro, cetriolo e peperone sotto acqua corrente senza sapone e asciuga. Pesa 500 g di pomodoro senza peduncolo, 300 g di cetriolo con buccia, 120 g di peperone senza picciolo né semi e 80 g di cipolla sbucciata. Scola e pesa 160 g di feta pastorizzata e 80 g di olive nere commerciali già mature e denocciolate; escludi il liquido di conserva. Pesa separatamente 30 g di olio, 20 g di aceto, 1 g di origano e 1 g di sale. Prevedi circa 5 minuti e segui le etichette di formaggio e olive; conserva il formaggio in frigorifero fino al taglio.", "image_url": "/recetas/receta-de-ensalada-griega/paso-01.webp", "image_alt": "Proposta di insalata greca con feta e olive: Lavare e pesare"}, {"title": "Tagliare verdure e formaggio", "content": "Taglia il pomodoro in pezzi di circa 2 cm, il cetriolo con buccia a mezze rondelle di circa 1 cm, il peperone a strisce e la cipolla a fettine sottili. Conserva i semi commestibili e i succhi del pomodoro, senza scolare le verdure. Taglia la feta a cubetti con utensili puliti senza sbriciolarla. Controlla che nessuna oliva conservi il nocciolo. Prevedi circa 8 minuti e riunisci verdure e olive nella ciotola; tieni la feta al freddo.", "image_url": "/recetas/receta-de-ensalada-griega/paso-02.webp", "image_alt": "Proposta di insalata greca con feta e olive: Tagliare verdure e formaggio"}, {"title": "Preparare il condimento pesato", "content": "Mescola in una ciotola piccola i 30 g di olio, i 20 g di aceto, il 1 g di origano e il 1 g di sale fino a distribuirli, per circa 3 minuti. Non aggiungere miele, senape, limone o altri condimenti. Il composto può separarsi di nuovo: mescola subito prima dell’uso e utilizzalo tutto. È una versione proposta d’ispirazione greca, senza rivendicare un’unica formula tradizionale.", "image_url": "/recetas/receta-de-ensalada-griega/paso-03.webp", "image_alt": "Proposta di insalata greca con feta e olive: Preparare il condimento pesato"}, {"title": "Mescolare senza rompere la feta", "content": "Versa tutto il condimento su pomodoro, cetriolo, peperone, cipolla e olive; mescola delicatamente con due cucchiai puliti. Aggiungi tutti i cubetti di feta e gira poche volte per mantenerne la forma. Prevedi circa 2 minuti. Non aggiungere lattuga, pane, carne, capperi né altro olio o sale: non fanno parte della formula o del calcolo.", "image_url": "/recetas/receta-de-ensalada-griega/paso-04.webp", "image_alt": "Proposta di insalata greca con feta e olive: Mescolare senza rompere la feta"}, {"title": "Raffreddare coperto", "content": "Trasferisci tutta l’insalata, succhi e condimento compresi, in un contenitore poco profondo, copri e metti in frigorifero a 4 °C o meno per circa 30 minuti, finché è fredda; prolunga se necessario e aggiungi il tempo reale. Refrigerare gli alimenti deperibili entro 2 ore dalla preparazione, o 1 ora se la temperatura ambiente supera 32 °C. Non lasciare formaggio o insalata tiepida in attesa fuori dal frigorifero.", "image_url": "/recetas/receta-de-ensalada-griega/paso-05.webp", "image_alt": "Proposta di insalata greca con feta e olive: Raffreddare coperto"}, {"title": "Dividere e servire", "content": "Prevedi circa 2 minuti per dividere in 4 porzioni simili con feta, olive, verdure e tutti i succhi e il condimento. I 1292 g sono la somma iniziale pesata, non una resa finale misurata. Si propongono 50 minuti complessivi: preparazione 5, taglio 8, condimento 3, mescolatura 2, freddo 30 e divisione 2, senza cottura. Quantità, tempi e porzioni attendono conferma in cucina. Conserva coperto a 4 °C o meno; consumare entro 24 ore è una proposta di qualità non provata, non conservazione validata. Estrai solo quanto servirai, non riutilizzare avanzi del piatto e non valutare la sicurezza dall’odore.", "image_url": "/recetas/receta-de-ensalada-griega/portada.webp", "image_alt": "Proposta di insalata greca con feta e olive: Dividere e servire"}], "nutrition": {"calories": 244.9, "protein_g": 7.9, "carbs_g": 13.8, "fat_g": 18.7, "saturated_fat_g": 6.9, "fiber_g": 3.2, "sugar_g": 6.1, "sodium_mg": 710.1, "estimated": true, "source": "USDA FoodData Central — SR Legacy", "source_url": "https://fdc.nal.usda.gov/download-datasets/", "inputs": [{"ingredient": "pomodoro rosso maturo senza peduncolo", "edible_grams": 500, "fdc_id": 170457, "fdc_description": "Tomatoes, red, ripe, raw, year round average", "per_100g": {"calories": 18.0, "protein_g": 0.88, "carbs_g": 3.89, "fat_g": 0.2, "saturated_fat_g": 0.028, "fiber_g": 1.2, "sugar_g": 2.63, "sodium_mg": 5.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170457/nutrients"}, {"ingredient": "cetriolo pulito con buccia", "edible_grams": 300, "fdc_id": 168409, "fdc_description": "Cucumber, with peel, raw", "per_100g": {"calories": 15.0, "protein_g": 0.65, "carbs_g": 3.63, "fat_g": 0.11, "saturated_fat_g": 0.037, "fiber_g": 0.5, "sugar_g": 1.67, "sodium_mg": 2.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168409/nutrients"}, {"ingredient": "peperone verde senza picciolo né semi", "edible_grams": 120, "fdc_id": 170427, "fdc_description": "Peppers, sweet, green, raw", "per_100g": {"calories": 20.0, "protein_g": 0.86, "carbs_g": 4.64, "fat_g": 0.17, "saturated_fat_g": 0.058, "fiber_g": 1.7, "sugar_g": 2.4, "sodium_mg": 3.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170427/nutrients"}, {"ingredient": "cipolla rossa sbucciata", "edible_grams": 80, "fdc_id": 170000, "fdc_description": "Onions, raw", "per_100g": {"calories": 40.0, "protein_g": 1.1, "carbs_g": 9.34, "fat_g": 0.1, "saturated_fat_g": 0.042, "fiber_g": 1.7, "sugar_g": 4.24, "sodium_mg": 4.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170000/nutrients"}, {"ingredient": "feta intera da latte pastorizzato, scolata", "edible_grams": 160, "fdc_id": 173420, "fdc_description": "Cheese, feta", "per_100g": {"calories": 265, "protein_g": 14.2, "carbs_g": 3.88, "fat_g": 21.5, "saturated_fat_g": 13.3, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 1140.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173420/nutrients"}, {"ingredient": "olive nere mature in conserva commerciale, denocciolate e scolate, da piccole a extra-grandi", "edible_grams": 80, "fdc_id": 169094, "fdc_description": "Olives, ripe, canned (small-extra large)", "per_100g": {"calories": 116, "protein_g": 0.84, "carbs_g": 6.04, "fat_g": 10.9, "saturated_fat_g": 2.28, "fiber_g": 1.6, "sugar_g": 0.0, "sodium_mg": 735}, "source_url": "https://fdc.nal.usda.gov/food-details/169094/nutrients"}, {"ingredient": "olio d’oliva", "edible_grams": 30, "fdc_id": 171413, "fdc_description": "Oil, olive, salad or cooking", "per_100g": {"calories": 884, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 100, "saturated_fat_g": 13.8, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 2.0}, "source_url": "https://fdc.nal.usda.gov/food-details/171413/nutrients"}, {"ingredient": "aceto di vino rosso", "edible_grams": 20, "fdc_id": 172240, "fdc_description": "Vinegar, red wine", "per_100g": {"calories": 19.0, "protein_g": 0.04, "carbs_g": 0.27, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 8.0}, "source_url": "https://fdc.nal.usda.gov/food-details/172240/nutrients"}, {"ingredient": "origano secco", "edible_grams": 1, "fdc_id": 171328, "fdc_description": "Spices, oregano, dried", "per_100g": {"calories": 265, "protein_g": 9.0, "carbs_g": 68.9, "fat_g": 4.28, "saturated_fat_g": 1.55, "fiber_g": 42.5, "sugar_g": 4.09, "sodium_mg": 25.0}, "source_url": "https://fdc.nal.usda.gov/food-details/171328/nutrients"}, {"ingredient": "sale fino", "edible_grams": 1, "fdc_id": 173468, "fdc_description": "Salt, table", "per_100g": {"calories": 0.0, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 38800.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173468/nutrients"}], "serving_size": "Un quarto dell’insalata con tutto il condimento; 4 porzioni proposte", "method": "Somma dei grammi commestibili moltiplicati per i valori USDA per 100 g, divisa per 4. Dieci alimenti esatti e otto nutrienti riportati per ciascuno; nessun dato mancante inventato.", "note": "Stima da confermare, non analisi né prova in cucina. 1292 g è il peso iniziale, non resa finale misurata. Feta intera USDA generica, non analisi di una specifica marca pastorizzata. Olive mature in conserva 169094, da piccole a extra-grandi, non Kalamata o giganti; 80 g scolate senza salamoia. Cipolla USDA generica, non analisi di una precisa varietà rossa. Include buccia commestibile, semi, succhi, tutti i 30 g di olio, 20 g di aceto, 1 g di sale e 1 g di origano. Nessuna perdita o riduzione del sodio per scolatura inventata. Marche, umidità e sale variano; accompagnamenti esclusi."}, "image_url": "/recetas/receta-de-ensalada-griega/portada.webp", "gallery": [{"url": "/recetas/receta-de-ensalada-griega/portada.webp", "alt": "Pomodoro rosso, mezze rondelle di cetriolo con buccia, peperone verde, cipolla rossa, olive nere e cubetti di feta con condimento all’origano, senza lattuga"}], "published": false, "editorial_status": "draft", "keywords": ["insalata greca", "insalata con feta", "insalata senza lattuga"], "notes": "Proposta d’ispirazione greca senza lattuga e senza rivendicare un’unica formula tradizionale. Il formaggio deve essere da latte pastorizzato e conservato secondo etichetta. Contiene latte; verifica ingredienti e tracce di tutti i prodotti. Il calcolo usa olive nere mature commerciali generiche in conserva, da piccole a extra-grandi, non Kalamata o giganti; cambiarle richiede adattamento e ricalcolo. Pesa feta e olive dopo scolatura, senza liquido di conserva. Sostituire o togliere feta cambia gusto, allergeni e valori nutrizionali; non sono garantite equivalenza o idoneità per allergie. Include tutta la buccia commestibile del cetriolo, semi e succhi del pomodoro, condimento e sale. Niente pane o condimenti extra. Lava le verdure sotto acqua corrente senza sapone e usa utensili puliti separati da alimenti crudi che richiedono cottura. Mantieni a 4 °C o meno e refrigerare entro 2 ore, o 1 ora sopra 32 °C. L’aceto non rende stabile l’insalata a temperatura ambiente. Le 24 ore proposte sono un criterio di qualità non provato, non durata validata; nessun tempo di congelamento stabilito. Non si affermano prove in cucina o benefici per la salute.", "seo": {"title": "Insalata greca con feta e olive, passo dopo passo", "description": "Pomodoro, cetriolo, peperone, feta e olive: quantità per quattro porzioni proposte, condimento pesato, raffreddamento e conservazione.", "image_alt": "Pomodoro rosso, mezze rondelle di cetriolo con buccia, peperone verde, cipolla rossa, olive nere e cubetti di feta con condimento all’origano, senza lattuga", "image_variants": ["/recetas/receta-de-ensalada-griega/portada-1x1.webp", "/recetas/receta-de-ensalada-griega/portada-4x3.webp", "/recetas/receta-de-ensalada-griega/portada-16x9.webp"], "faq": [{"q": "Servono lattuga o olive Kalamata?", "a": "Questa proposta non contiene lattuga e usa olive nere mature commerciali corrispondenti alla scheda USDA calcolata. Non sono presentate come Kalamata o unica formula tradizionale. Cambiare olive modifica gusto e composizione; rivedi quantità e calcolo."}, {"q": "Come limitare il liquido e mantenere integra la feta?", "a": "Asciuga le verdure lavate, scola formaggio e olive prima di pesarli e unisci delicatamente la feta per ultima. Conserva i succhi del pomodoro: appartengono alla formula. Un’attesa più lunga può liberare altro liquido; non si afferma che questa consistenza sia stata provata in cucina."}, {"q": "Quanto tempo serve e come si conserva?", "a": "Si propongono 50 minuti, inclusi 30 al freddo, senza cottura. Aggiungi il tempo reale se serve altro raffreddamento. Mantieni a 4 °C o meno e refrigerare entro 2 ore, o 1 ora sopra 32 °C. Consumare entro 24 ore è una proposta di qualità non provata; l’aceto non permette conservazione a temperatura ambiente."}]}, "content_html": "<p>Una proposta di insalata d’ispirazione greca con pomodoro, cetriolo, peperone verde, cipolla, feta pastorizzata e olive nere mature. Si propongono 4 porzioni e 50 minuti complessivi, di cui 30 al freddo, senza cottura. Quantità e tempi attendono conferma in cucina.</p><p>Proposta d’ispirazione greca senza lattuga e senza rivendicare un’unica formula tradizionale. Il formaggio deve essere da latte pastorizzato e conservato secondo etichetta. Contiene latte; verifica ingredienti e tracce di tutti i prodotti. Il calcolo usa olive nere mature commerciali generiche in conserva, da piccole a extra-grandi, non Kalamata o giganti; cambiarle richiede adattamento e ricalcolo. Pesa feta e olive dopo scolatura, senza liquido di conserva. Sostituire o togliere feta cambia gusto, allergeni e valori nutrizionali; non sono garantite equivalenza o idoneità per allergie. Include tutta la buccia commestibile del cetriolo, semi e succhi del pomodoro, condimento e sale. Niente pane o condimenti extra. Lava le verdure sotto acqua corrente senza sapone e usa utensili puliti separati da alimenti crudi che richiedono cottura. Mantieni a 4 °C o meno e refrigerare entro 2 ore, o 1 ora sopra 32 °C. L’aceto non rende stabile l’insalata a temperatura ambiente. Le 24 ore proposte sono un criterio di qualità non provato, non durata validata; nessun tempo di congelamento stabilito. Non si affermano prove in cucina o benefici per la salute.</p>"}, {"id": "2713f5b7-4fc4-580a-b688-821820bafc45", "recipe_group_id": "031f1a9c-6240-4ab4-9027-568a18de7ffe", "slug": "ギリシャ風サラダ", "public_path": "/ja/ギリシャ風サラダ", "source_url": null, "language": "ja", "title": "フェタチーズとオリーブのギリシャ風サラダ案", "excerpt": "トマト、きゅうり、フェタ、オリーブを計量したドレッシングで和える、レタスなしの四人分の提案。冷やす時間も含みます。", "summary": "トマト、きゅうり、緑のピーマン、玉ねぎ、殺菌乳製フェタ、完熟黒オリーブのギリシャ風サラダ案です。4人分、冷却30分を含め合計50分を提案します。加熱はせず、分量と時間は調理での確認待ちです。", "category": "サラダ", "category_slug": "ensaladas", "difficulty": "簡単", "course": "サラダ", "cuisine": "ギリシャ風", "prep_time_minutes": 20, "cook_time_minutes": 0, "total_time_minutes": 50, "servings": 4, "ingredients": [{"name": "熟した赤いトマト、へたを除く", "amount": "500", "unit": "g", "group": "サラダ"}, {"name": "洗ったきゅうり、皮付き", "amount": "300", "unit": "g", "group": "サラダ"}, {"name": "緑のピーマン、へたと種を除く", "amount": "120", "unit": "g", "group": "サラダ"}, {"name": "赤玉ねぎ、皮をむく", "amount": "80", "unit": "g", "group": "サラダ"}, {"name": "殺菌乳製の全脂肪フェタチーズ、水切りする", "amount": "160", "unit": "g", "group": "サラダ"}, {"name": "市販の完熟黒オリーブ缶詰、小粒から特大粒、種を除いて水切りする", "amount": "80", "unit": "g", "group": "サラダ"}, {"name": "オリーブ油", "amount": "30", "unit": "g", "group": "ドレッシング"}, {"name": "赤ワインビネガー", "amount": "20", "unit": "g", "group": "ドレッシング"}, {"name": "乾燥オレガノ", "amount": "1", "unit": "g", "group": "ドレッシング"}, {"name": "細粒塩", "amount": "1", "unit": "g", "group": "ドレッシング"}], "steps": [{"title": "洗って計量する", "content": "手を洗い、はかり、まな板、包丁、大きなボウル、ふた付き容器を用意します。トマト、きゅうり、ピーマンを石けんを使わず流水で洗い、水気を拭きます。へたを除いたトマト500 g、皮付ききゅうり300 g、へたと種を除いたピーマン120 g、皮をむいた玉ねぎ80 gを量ります。殺菌乳製フェタ160 gと市販の完熟黒オリーブの種なし果肉80 gは水切り後に量り、保存液は使いません。別に油30 g、ビネガー20 g、オレガノ1 g、塩1 gを量ります。約5分を見込み、チーズとオリーブの表示に従い、チーズは切る直前まで冷蔵します。", "image_url": "/recetas/receta-de-ensalada-griega/paso-01.webp", "image_alt": "フェタチーズとオリーブのギリシャ風サラダ案: 洗って計量する"}, {"title": "野菜とチーズを切る", "content": "トマトを約2 cm角、皮付ききゅうりを厚さ約1 cmの半月切り、ピーマンを細長く、玉ねぎを薄く切ります。トマトの食べられる種と汁は残し、野菜を水切りしません。清潔な器具でフェタを角切りにし、崩さないようにします。すべてのオリーブに種が残っていないことを確認します。約8分を見込み、野菜とオリーブをボウルに集め、フェタは冷蔵しておきます。", "image_url": "/recetas/receta-de-ensalada-griega/paso-02.webp", "image_alt": "フェタチーズとオリーブのギリシャ風サラダ案: 野菜とチーズを切る"}, {"title": "計量したドレッシングを混ぜる", "content": "小さなボウルで油30 g、ビネガー20 g、オレガノ1 g、塩1 gを約3分混ぜ、全体に分散させます。はちみつ、マスタード、レモン、追加の調味料は入れません。再び分離することがあるため、使う直前に混ぜ、全量を使います。ギリシャ風の提案であり、唯一の伝統的配合とは主張しません。", "image_url": "/recetas/receta-de-ensalada-griega/paso-03.webp", "image_alt": "フェタチーズとオリーブのギリシャ風サラダ案: 計量したドレッシングを混ぜる"}, {"title": "フェタを崩さず和える", "content": "トマト、きゅうり、ピーマン、玉ねぎ、オリーブにドレッシングを全量加え、清潔なスプーン二本で優しく混ぜます。フェタの角切りをすべて入れ、形を保つため少ない回数で返します。約2分を見込みます。レタス、パン、肉、ケイパー、追加の油や塩は配合にも計算にも含まれないため、加えません。", "image_url": "/recetas/receta-de-ensalada-griega/paso-04.webp", "image_alt": "フェタチーズとオリーブのギリシャ風サラダ案: フェタを崩さず和える"}, {"title": "ふたをして冷やす", "content": "汁とドレッシングを含むサラダ全量を浅い容器に移し、ふたをして4 °C以下で約30分、冷たくなるまで冷蔵します。必要なら延長し、実際の時間を加算します。傷みやすい食品は準備後2時間以内、室温が32 °Cを超える場合は1時間以内に冷蔵します。チーズやぬるいサラダを冷蔵庫の外で待たせないでください。", "image_url": "/recetas/receta-de-ensalada-griega/paso-05.webp", "image_alt": "フェタチーズとオリーブのギリシャ風サラダ案: ふたをして冷やす"}, {"title": "分けて提供する", "content": "約2分で、フェタ、オリーブ、野菜、すべての汁とドレッシングを含む同程度の4人分に分けます。1292 gは最初に量った合計であり、完成品の実測重量ではありません。合計50分の提案は、準備5、切る作業8、ドレッシング3、混ぜる作業2、冷却30、取り分け2で、加熱はありません。分量、時間、人数は調理での確認待ちです。ふたをして4 °C以下で保存し、24時間以内に食べる目安は未検証の品質上の提案で、保存期間の検証結果ではありません。提供する分だけ取り出し、皿の食べ残しを戻さず、においだけで安全性を判断しません。", "image_url": "/recetas/receta-de-ensalada-griega/portada.webp", "image_alt": "フェタチーズとオリーブのギリシャ風サラダ案: 分けて提供する"}], "nutrition": {"calories": 244.9, "protein_g": 7.9, "carbs_g": 13.8, "fat_g": 18.7, "saturated_fat_g": 6.9, "fiber_g": 3.2, "sugar_g": 6.1, "sodium_mg": 710.1, "estimated": true, "source": "USDA FoodData Central — SR Legacy", "source_url": "https://fdc.nal.usda.gov/download-datasets/", "inputs": [{"ingredient": "熟した赤いトマト、へたを除く", "edible_grams": 500, "fdc_id": 170457, "fdc_description": "Tomatoes, red, ripe, raw, year round average", "per_100g": {"calories": 18.0, "protein_g": 0.88, "carbs_g": 3.89, "fat_g": 0.2, "saturated_fat_g": 0.028, "fiber_g": 1.2, "sugar_g": 2.63, "sodium_mg": 5.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170457/nutrients"}, {"ingredient": "洗ったきゅうり、皮付き", "edible_grams": 300, "fdc_id": 168409, "fdc_description": "Cucumber, with peel, raw", "per_100g": {"calories": 15.0, "protein_g": 0.65, "carbs_g": 3.63, "fat_g": 0.11, "saturated_fat_g": 0.037, "fiber_g": 0.5, "sugar_g": 1.67, "sodium_mg": 2.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168409/nutrients"}, {"ingredient": "緑のピーマン、へたと種を除く", "edible_grams": 120, "fdc_id": 170427, "fdc_description": "Peppers, sweet, green, raw", "per_100g": {"calories": 20.0, "protein_g": 0.86, "carbs_g": 4.64, "fat_g": 0.17, "saturated_fat_g": 0.058, "fiber_g": 1.7, "sugar_g": 2.4, "sodium_mg": 3.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170427/nutrients"}, {"ingredient": "赤玉ねぎ、皮をむく", "edible_grams": 80, "fdc_id": 170000, "fdc_description": "Onions, raw", "per_100g": {"calories": 40.0, "protein_g": 1.1, "carbs_g": 9.34, "fat_g": 0.1, "saturated_fat_g": 0.042, "fiber_g": 1.7, "sugar_g": 4.24, "sodium_mg": 4.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170000/nutrients"}, {"ingredient": "殺菌乳製の全脂肪フェタチーズ、水切りする", "edible_grams": 160, "fdc_id": 173420, "fdc_description": "Cheese, feta", "per_100g": {"calories": 265, "protein_g": 14.2, "carbs_g": 3.88, "fat_g": 21.5, "saturated_fat_g": 13.3, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 1140.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173420/nutrients"}, {"ingredient": "市販の完熟黒オリーブ缶詰、小粒から特大粒、種を除いて水切りする", "edible_grams": 80, "fdc_id": 169094, "fdc_description": "Olives, ripe, canned (small-extra large)", "per_100g": {"calories": 116, "protein_g": 0.84, "carbs_g": 6.04, "fat_g": 10.9, "saturated_fat_g": 2.28, "fiber_g": 1.6, "sugar_g": 0.0, "sodium_mg": 735}, "source_url": "https://fdc.nal.usda.gov/food-details/169094/nutrients"}, {"ingredient": "オリーブ油", "edible_grams": 30, "fdc_id": 171413, "fdc_description": "Oil, olive, salad or cooking", "per_100g": {"calories": 884, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 100, "saturated_fat_g": 13.8, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 2.0}, "source_url": "https://fdc.nal.usda.gov/food-details/171413/nutrients"}, {"ingredient": "赤ワインビネガー", "edible_grams": 20, "fdc_id": 172240, "fdc_description": "Vinegar, red wine", "per_100g": {"calories": 19.0, "protein_g": 0.04, "carbs_g": 0.27, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 8.0}, "source_url": "https://fdc.nal.usda.gov/food-details/172240/nutrients"}, {"ingredient": "乾燥オレガノ", "edible_grams": 1, "fdc_id": 171328, "fdc_description": "Spices, oregano, dried", "per_100g": {"calories": 265, "protein_g": 9.0, "carbs_g": 68.9, "fat_g": 4.28, "saturated_fat_g": 1.55, "fiber_g": 42.5, "sugar_g": 4.09, "sodium_mg": 25.0}, "source_url": "https://fdc.nal.usda.gov/food-details/171328/nutrients"}, {"ingredient": "細粒塩", "edible_grams": 1, "fdc_id": 173468, "fdc_description": "Salt, table", "per_100g": {"calories": 0.0, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 38800.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173468/nutrients"}], "serving_size": "ドレッシング全量を含むサラダの四分の一；提案は4人分", "method": "食べられる重量にUSDAの100 g当たり値を掛けて合計し、4で割ります。正確に確認した十食品すべてで八栄養素が報告されており、欠けたデータを作りません。", "note": "確認待ちの推定で、分析値や調理試験の結果ではありません。1292 gは最初の重量で、完成重量の実測ではありません。USDAの一般的な全脂肪フェタで、特定の殺菌乳製ブランドの分析ではありません。169094は小粒から特大粒の完熟オリーブ缶詰で、カラマタや巨大粒ではなく、保存液を除く水切り後80 gです。玉ねぎも一般的なUSDAデータで、特定の赤玉ねぎ品種の分析ではありません。食べられる皮、種、汁、油30 g、ビネガー20 g、塩1 g、オレガノ1 gをすべて含みます。水切りによる損失やナトリウム低下を架空に設定しません。銘柄、水分、塩分で変わり、付け合わせは含みません。"}, "image_url": "/recetas/receta-de-ensalada-griega/portada.webp", "gallery": [{"url": "/recetas/receta-de-ensalada-griega/portada.webp", "alt": "赤いトマト、皮付ききゅうりの半月切り、緑のピーマン、赤玉ねぎ、黒オリーブ、フェタの角切りをオレガノ入りドレッシングで和えたレタスなしのサラダ"}], "published": false, "editorial_status": "draft", "keywords": ["ギリシャ風サラダ", "フェタのサラダ", "レタスなしサラダ"], "notes": "レタスを使わないギリシャ風の提案で、唯一の伝統的配合とは主張しません。チーズは殺菌乳製を選び、表示どおりに保存します。乳を含みます。全製品の原材料と交差接触の表示を確認してください。計算には市販の一般的な完熟黒オリーブ缶詰の小粒から特大粒を使い、カラマタや巨大粒ではありません。変更時は配合調整と再計算が必要です。フェタとオリーブは保存液を除いた水切り後の重量です。フェタを別のチーズに替える、または除くと、味、アレルゲン、栄養が変わり、同じ結果やアレルギーへの適合を保証しません。きゅうりの食べられる皮、トマトの種と汁、ドレッシングと塩をすべて含みます。パンや追加の調味料は加えません。野菜は石けんを使わず流水で洗い、加熱が必要な生食品とは器具を分けて清潔に扱います。4 °C以下で保ち、2時間以内、32 °Cを超える場合は1時間以内に冷蔵します。酢を入れても常温保存できる食品にはなりません。提案する24時間は未検証の品質目安であり、検証済みの保存期限ではなく、冷凍期間も設定しません。調理試験や健康効果は主張しません。", "seo": {"title": "フェタとオリーブのギリシャ風サラダ：手順と冷却", "description": "トマト、きゅうり、ピーマン、フェタ、オリーブ。四人分の提案と計量したドレッシング、冷却、保存の手順を説明します。", "image_alt": "赤いトマト、皮付ききゅうりの半月切り、緑のピーマン、赤玉ねぎ、黒オリーブ、フェタの角切りをオレガノ入りドレッシングで和えたレタスなしのサラダ", "image_variants": ["/recetas/receta-de-ensalada-griega/portada-1x1.webp", "/recetas/receta-de-ensalada-griega/portada-4x3.webp", "/recetas/receta-de-ensalada-griega/portada-16x9.webp"], "faq": [{"q": "レタスやカラマタオリーブは必要ですか？", "a": "この提案ではレタスを使わず、USDAの計算用食品データに合わせて市販の完熟黒オリーブを使います。カラマタとも、唯一の伝統的配合とも説明しません。種類を変えると味と成分が変わり、分量と計算の見直しが必要です。"}, {"q": "水っぽさを抑え、フェタの形を保つには？", "a": "洗った野菜を拭き、チーズとオリーブは水切り後に量り、フェタを最後に優しく混ぜます。トマトの汁は配合の一部なので残します。長く置くと汁が増える場合があり、この食感を調理試験済みとは主張しません。"}, {"q": "所要時間と保存方法は？", "a": "加熱なしで、冷却30分を含む合計50分を提案します。冷却が延びた場合は実際の時間を加算します。4 °C以下で保ち、2時間以内、32 °Cを超える場合は1時間以内に冷蔵します。24時間以内という目安は未検証の品質提案で、酢を入れても常温には置けません。"}]}, "content_html": "<p>トマト、きゅうり、緑のピーマン、玉ねぎ、殺菌乳製フェタ、完熟黒オリーブのギリシャ風サラダ案です。4人分、冷却30分を含め合計50分を提案します。加熱はせず、分量と時間は調理での確認待ちです。</p><p>レタスを使わないギリシャ風の提案で、唯一の伝統的配合とは主張しません。チーズは殺菌乳製を選び、表示どおりに保存します。乳を含みます。全製品の原材料と交差接触の表示を確認してください。計算には市販の一般的な完熟黒オリーブ缶詰の小粒から特大粒を使い、カラマタや巨大粒ではありません。変更時は配合調整と再計算が必要です。フェタとオリーブは保存液を除いた水切り後の重量です。フェタを別のチーズに替える、または除くと、味、アレルゲン、栄養が変わり、同じ結果やアレルギーへの適合を保証しません。きゅうりの食べられる皮、トマトの種と汁、ドレッシングと塩をすべて含みます。パンや追加の調味料は加えません。野菜は石けんを使わず流水で洗い、加熱が必要な生食品とは器具を分けて清潔に扱います。4 °C以下で保ち、2時間以内、32 °Cを超える場合は1時間以内に冷蔵します。酢を入れても常温保存できる食品にはなりません。提案する24時間は未検証の品質目安であり、検証済みの保存期限ではなく、冷凍期間も設定しません。調理試験や健康効果は主張しません。</p>"}, {"id": "fd54c34e-233a-5044-a443-c54331e5a09d", "recipe_group_id": "031f1a9c-6240-4ab4-9027-568a18de7ffe", "slug": "salada-grega", "public_path": "/pt/salada-grega", "source_url": null, "language": "pt", "title": "Proposta de salada grega com feta e azeitonas", "excerpt": "Tomate, pepino, feta e azeitonas com molho pesado, sem alface e com refrigeração para quatro porções propostas.", "summary": "Uma proposta de salada de inspiração grega com tomate, pepino, pimentão verde, cebola, feta pasteurizado e azeitonas pretas maduras. São propostas 4 porções e 50 minutos completos, incluindo 30 de refrigeração, sem cozimento. Quantidades e tempos aguardam confirmação na cozinha.", "category": "Saladas", "category_slug": "ensaladas", "difficulty": "Fácil", "course": "Salada", "cuisine": "Inspiração grega", "prep_time_minutes": 20, "cook_time_minutes": 0, "total_time_minutes": 50, "servings": 4, "ingredients": [{"name": "tomate vermelho maduro sem pedúnculo", "amount": "500", "unit": "g", "group": "Salada"}, {"name": "pepino limpo com casca", "amount": "300", "unit": "g", "group": "Salada"}, {"name": "pimentão verde sem talo nem sementes", "amount": "120", "unit": "g", "group": "Salada"}, {"name": "cebola-roxa descascada", "amount": "80", "unit": "g", "group": "Salada"}, {"name": "queijo feta integral de leite pasteurizado, escorrido", "amount": "160", "unit": "g", "group": "Salada"}, {"name": "azeitonas pretas maduras em conserva comercial, sem caroço e escorridas, pequenas a extragrandes", "amount": "80", "unit": "g", "group": "Salada"}, {"name": "azeite de oliva", "amount": "30", "unit": "g", "group": "Molho"}, {"name": "vinagre de vinho tinto", "amount": "20", "unit": "g", "group": "Molho"}, {"name": "orégano seco", "amount": "1", "unit": "g", "group": "Molho"}, {"name": "sal fino", "amount": "1", "unit": "g", "group": "Molho"}], "steps": [{"title": "Lave e pese", "content": "Lave as mãos e prepare balança, tábua, faca, tigela grande e recipiente com tampa. Lave tomate, pepino e pimentão em água corrente sem sabão e seque. Pese 500 g de tomate sem pedúnculo, 300 g de pepino com casca, 120 g de pimentão sem talo nem sementes e 80 g de cebola descascada. Escorra e pese 160 g de feta pasteurizado e 80 g de azeitonas pretas comerciais já maduras, sem caroço; não use o líquido da conserva. Pese separadamente 30 g de azeite, 20 g de vinagre, 1 g de orégano e 1 g de sal. Reserve cerca de 5 minutos e siga os rótulos do queijo e das azeitonas; mantenha o queijo refrigerado até cortar.", "image_url": "/recetas/receta-de-ensalada-griega/paso-01.webp", "image_alt": "Proposta de salada grega com feta e azeitonas: Lave e pese"}, {"title": "Corte os vegetais e o queijo", "content": "Corte o tomate em pedaços de cerca de 2 cm, o pepino com casca em meias-luas de cerca de 1 cm, o pimentão em tiras e a cebola em fatias finas. Preserve sementes comestíveis e sucos do tomate, sem escorrer os vegetais. Corte o feta em cubos com utensílios limpos, sem esfarelar. Confira se todas as azeitonas estão sem caroço. Reserve cerca de 8 minutos e reúna vegetais e azeitonas na tigela; mantenha o feta refrigerado.", "image_url": "/recetas/receta-de-ensalada-griega/paso-02.webp", "image_alt": "Proposta de salada grega com feta e azeitonas: Corte os vegetais e o queijo"}, {"title": "Prepare o molho pesado", "content": "Misture em uma tigela pequena os 30 g de azeite, os 20 g de vinagre, o 1 g de orégano e o 1 g de sal até dispersar, por cerca de 3 minutos. Não acrescente mel, mostarda, limão ou temperos extras. O molho pode voltar a separar: mexa imediatamente antes de usar e aproveite todo o conteúdo. É uma versão proposta de inspiração grega, sem afirmar uma fórmula tradicional única.", "image_url": "/recetas/receta-de-ensalada-griega/paso-03.webp", "image_alt": "Proposta de salada grega com feta e azeitonas: Prepare o molho pesado"}, {"title": "Misture sem quebrar o feta", "content": "Despeje todo o molho sobre tomate, pepino, pimentão, cebola e azeitonas; misture delicadamente com duas colheres limpas. Acrescente todos os cubos de feta e vire poucas vezes para manter a forma. Reserve cerca de 2 minutos. Não acrescente alface, pão, carne, alcaparras nem mais azeite ou sal: não estão nesta fórmula nem no cálculo.", "image_url": "/recetas/receta-de-ensalada-griega/paso-04.webp", "image_alt": "Proposta de salada grega com feta e azeitonas: Misture sem quebrar o feta"}, {"title": "Refrigere tampada", "content": "Transfira toda a salada, incluindo sucos e molho, para um recipiente raso, tampe e refrigere a 4 °C ou menos por cerca de 30 minutos, até ficar fria; prolongue se necessário e some o tempo real. Refrigere perecíveis dentro de 2 horas após o preparo, ou 1 hora se a temperatura ambiente ultrapassar 32 °C. Não deixe o queijo ou a salada morna esperando fora da geladeira.", "image_url": "/recetas/receta-de-ensalada-griega/paso-05.webp", "image_alt": "Proposta de salada grega com feta e azeitonas: Refrigere tampada"}, {"title": "Divida e sirva", "content": "Reserve cerca de 2 minutos para dividir em 4 porções semelhantes, com feta, azeitonas, vegetais e todos os sucos e o molho. Os 1292 g são a soma inicial pesada, não um rendimento final medido. Propõem-se 50 minutos completos: preparo 5, corte 8, molho 3, mistura 2, refrigeração 30 e divisão 2, sem cozimento. Quantidades, tempos e porções aguardam confirmação na cozinha. Guarde tampada a 4 °C ou menos; consumir em 24 horas é uma proposta de qualidade não testada, não conservação validada. Retire apenas o que servirá, não reaproveite sobras do prato e não julgue segurança pelo cheiro.", "image_url": "/recetas/receta-de-ensalada-griega/portada.webp", "image_alt": "Proposta de salada grega com feta e azeitonas: Divida e sirva"}], "nutrition": {"calories": 244.9, "protein_g": 7.9, "carbs_g": 13.8, "fat_g": 18.7, "saturated_fat_g": 6.9, "fiber_g": 3.2, "sugar_g": 6.1, "sodium_mg": 710.1, "estimated": true, "source": "USDA FoodData Central — SR Legacy", "source_url": "https://fdc.nal.usda.gov/download-datasets/", "inputs": [{"ingredient": "tomate vermelho maduro sem pedúnculo", "edible_grams": 500, "fdc_id": 170457, "fdc_description": "Tomatoes, red, ripe, raw, year round average", "per_100g": {"calories": 18.0, "protein_g": 0.88, "carbs_g": 3.89, "fat_g": 0.2, "saturated_fat_g": 0.028, "fiber_g": 1.2, "sugar_g": 2.63, "sodium_mg": 5.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170457/nutrients"}, {"ingredient": "pepino limpo com casca", "edible_grams": 300, "fdc_id": 168409, "fdc_description": "Cucumber, with peel, raw", "per_100g": {"calories": 15.0, "protein_g": 0.65, "carbs_g": 3.63, "fat_g": 0.11, "saturated_fat_g": 0.037, "fiber_g": 0.5, "sugar_g": 1.67, "sodium_mg": 2.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168409/nutrients"}, {"ingredient": "pimentão verde sem talo nem sementes", "edible_grams": 120, "fdc_id": 170427, "fdc_description": "Peppers, sweet, green, raw", "per_100g": {"calories": 20.0, "protein_g": 0.86, "carbs_g": 4.64, "fat_g": 0.17, "saturated_fat_g": 0.058, "fiber_g": 1.7, "sugar_g": 2.4, "sodium_mg": 3.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170427/nutrients"}, {"ingredient": "cebola-roxa descascada", "edible_grams": 80, "fdc_id": 170000, "fdc_description": "Onions, raw", "per_100g": {"calories": 40.0, "protein_g": 1.1, "carbs_g": 9.34, "fat_g": 0.1, "saturated_fat_g": 0.042, "fiber_g": 1.7, "sugar_g": 4.24, "sodium_mg": 4.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170000/nutrients"}, {"ingredient": "queijo feta integral de leite pasteurizado, escorrido", "edible_grams": 160, "fdc_id": 173420, "fdc_description": "Cheese, feta", "per_100g": {"calories": 265, "protein_g": 14.2, "carbs_g": 3.88, "fat_g": 21.5, "saturated_fat_g": 13.3, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 1140.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173420/nutrients"}, {"ingredient": "azeitonas pretas maduras em conserva comercial, sem caroço e escorridas, pequenas a extragrandes", "edible_grams": 80, "fdc_id": 169094, "fdc_description": "Olives, ripe, canned (small-extra large)", "per_100g": {"calories": 116, "protein_g": 0.84, "carbs_g": 6.04, "fat_g": 10.9, "saturated_fat_g": 2.28, "fiber_g": 1.6, "sugar_g": 0.0, "sodium_mg": 735}, "source_url": "https://fdc.nal.usda.gov/food-details/169094/nutrients"}, {"ingredient": "azeite de oliva", "edible_grams": 30, "fdc_id": 171413, "fdc_description": "Oil, olive, salad or cooking", "per_100g": {"calories": 884, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 100, "saturated_fat_g": 13.8, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 2.0}, "source_url": "https://fdc.nal.usda.gov/food-details/171413/nutrients"}, {"ingredient": "vinagre de vinho tinto", "edible_grams": 20, "fdc_id": 172240, "fdc_description": "Vinegar, red wine", "per_100g": {"calories": 19.0, "protein_g": 0.04, "carbs_g": 0.27, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 8.0}, "source_url": "https://fdc.nal.usda.gov/food-details/172240/nutrients"}, {"ingredient": "orégano seco", "edible_grams": 1, "fdc_id": 171328, "fdc_description": "Spices, oregano, dried", "per_100g": {"calories": 265, "protein_g": 9.0, "carbs_g": 68.9, "fat_g": 4.28, "saturated_fat_g": 1.55, "fiber_g": 42.5, "sugar_g": 4.09, "sodium_mg": 25.0}, "source_url": "https://fdc.nal.usda.gov/food-details/171328/nutrients"}, {"ingredient": "sal fino", "edible_grams": 1, "fdc_id": 173468, "fdc_description": "Salt, table", "per_100g": {"calories": 0.0, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 38800.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173468/nutrients"}], "serving_size": "Um quarto da salada com todo o molho; 4 porções propostas", "method": "Soma dos gramas comestíveis multiplicados pelos valores USDA por 100 g, dividida por 4. Dez alimentos exatos e oito nutrientes informados em todos; dados ausentes nunca inventados.", "note": "Estimativa a confirmar, não análise nem teste na cozinha. Os 1292 g são peso inicial, não rendimento final medido. Feta integral USDA genérico, não análise de uma marca pasteurizada específica. Azeitonas 169094 maduras em conserva pequenas a extragrandes, não Kalamata nem gigantes; 80 g escorridas sem salmoura. Cebola USDA genérica, não análise de uma variedade roxa específica. Inclui casca comestível, sementes, sucos, todos os 30 g de azeite, 20 g de vinagre, 1 g de sal e 1 g de orégano. Não inventa perdas nem redução de sódio por escorrer. Marcas, umidade e sal variam; acompanhamentos excluídos."}, "image_url": "/recetas/receta-de-ensalada-griega/portada.webp", "gallery": [{"url": "/recetas/receta-de-ensalada-griega/portada.webp", "alt": "Tomate vermelho, meias-luas de pepino com casca, pimentão verde, cebola-roxa, azeitonas pretas e cubos de feta com molho de orégano, sem alface"}], "published": false, "editorial_status": "draft", "keywords": ["salada grega", "salada com feta", "salada sem alface"], "notes": "Proposta de inspiração grega sem alface, sem afirmar uma fórmula tradicional única. Use queijo de leite pasteurizado e conserve conforme o rótulo. Contém leite; confira ingredientes e informações de traços de todos os produtos. O cálculo usa azeitonas pretas maduras comerciais genéricas em conserva, pequenas a extragrandes, não Kalamata nem gigantes; trocar exige adaptar e recalcular. Pese feta e azeitonas depois de escorrer, sem líquido de conserva. Substituir ou retirar feta muda sabor, alérgenos e nutrição; não se garante equivalência nem adequação para alergias. Toda a casca comestível do pepino, sementes e sucos do tomate, molho e sal são incluídos. Não adiciona pão ou temperos extras. Lave vegetais em água corrente sem sabão e use utensílios limpos separados de alimentos crus que precisem de cozimento. Mantenha a 4 °C ou menos e refrigere dentro de 2 horas, ou 1 hora acima de 32 °C. Vinagre não torna a salada estável à temperatura ambiente. As 24 horas propostas são um critério de qualidade não testado, não validade comprovada; não se define prazo de congelamento. Não se afirma teste na cozinha nem benefício à saúde.", "seo": {"title": "Salada grega com feta e azeitonas, passo a passo", "description": "Tomate, pepino, pimentão, feta e azeitonas: quantidades para quatro porções propostas, molho pesado, refrigeração e conservação explicados.", "image_alt": "Tomate vermelho, meias-luas de pepino com casca, pimentão verde, cebola-roxa, azeitonas pretas e cubos de feta com molho de orégano, sem alface", "image_variants": ["/recetas/receta-de-ensalada-griega/portada-1x1.webp", "/recetas/receta-de-ensalada-griega/portada-4x3.webp", "/recetas/receta-de-ensalada-griega/portada-16x9.webp"], "faq": [{"q": "Leva alface ou precisa de azeitonas Kalamata?", "a": "Esta proposta não leva alface e usa azeitonas pretas maduras comerciais para corresponder à ficha USDA calculada. Não são apresentadas como Kalamata nem como fórmula tradicional única. Trocar azeitonas muda sabor e composição; reveja quantidades e cálculo."}, {"q": "Como limitar o líquido e preservar os cubos de feta?", "a": "Seque os vegetais lavados, escorra queijo e azeitonas antes de pesar e misture o feta delicadamente por último. Preserve os sucos do tomate: fazem parte da fórmula. Uma espera maior pode liberar mais líquido; não se afirma que essa textura tenha sido testada na cozinha."}, {"q": "Quanto tempo demora e como guardar?", "a": "Propõem-se 50 minutos, incluindo 30 de refrigeração, sem cozimento. Some o tempo real se precisar resfriar mais. Mantenha a 4 °C ou menos e refrigere dentro de 2 horas, ou 1 hora acima de 32 °C. Consumir em 24 horas é uma proposta de qualidade não testada; vinagre não permite deixar à temperatura ambiente."}]}, "content_html": "<p>Uma proposta de salada de inspiração grega com tomate, pepino, pimentão verde, cebola, feta pasteurizado e azeitonas pretas maduras. São propostas 4 porções e 50 minutos completos, incluindo 30 de refrigeração, sem cozimento. Quantidades e tempos aguardam confirmação na cozinha.</p><p>Proposta de inspiração grega sem alface, sem afirmar uma fórmula tradicional única. Use queijo de leite pasteurizado e conserve conforme o rótulo. Contém leite; confira ingredientes e informações de traços de todos os produtos. O cálculo usa azeitonas pretas maduras comerciais genéricas em conserva, pequenas a extragrandes, não Kalamata nem gigantes; trocar exige adaptar e recalcular. Pese feta e azeitonas depois de escorrer, sem líquido de conserva. Substituir ou retirar feta muda sabor, alérgenos e nutrição; não se garante equivalência nem adequação para alergias. Toda a casca comestível do pepino, sementes e sucos do tomate, molho e sal são incluídos. Não adiciona pão ou temperos extras. Lave vegetais em água corrente sem sabão e use utensílios limpos separados de alimentos crus que precisem de cozimento. Mantenha a 4 °C ou menos e refrigere dentro de 2 horas, ou 1 hora acima de 32 °C. Vinagre não torna a salada estável à temperatura ambiente. As 24 horas propostas são um critério de qualidade não testado, não validade comprovada; não se define prazo de congelamento. Não se afirma teste na cozinha nem benefício à saúde.</p>"}]$records$::jsonb;
 b constant jsonb := $before${"id": "fb8402a9-e0f5-4636-865a-1a7b3a92d5bf", "recipe_group_id": "031f1a9c-6240-4ab4-9027-568a18de7ffe", "slug": "receta-de-ensalada-griega", "public_path": "/receta-de-ensalada-griega", "source_url": "https://manualdecocina.com/receta-de-ensalada-griega/", "created_at": "2026-09-23 20:50:30.015432+00", "published_at": "2026-09-23 20:50:30.015432+00", "expected_row_md5": "f5d122fdea6c3d56502b30f64699b348"}$before$::jsonb;
